          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0a876673-a697-5786-ae72-76411a450615","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -قات -نقل بقصد االجتار -هروب املدعى عليه من رجال األمن -إقرار -التعزير بالسجن واجللد والغرامة.","document_number":"3460741","case_number":"34111631","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/11","year":"1434","subject":"مخدرات -قات -نقل بقصد االجتار -هروب املدعى عليه من رجال األمن -إقرار -التعزير بالسجن واجللد والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3460741:‬تاريخه‪1434/3/11:‬هـ‬\n                   ‫رقم الدعوى‪34111631:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34193498‬تاريخه‪1434/4/21 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬قــات ‪ -‬نقــل بقصــد االجتــار ‪ -‬هــروب املدعــى عليــه مــن رجال‬\n                  ‫األمــن ‪ -‬إقــرار ‪ -‬التعزيــر بالســجن واجللــد والغرامة‪.‬‬\n\n\n\n\n                     ‫‪ -1‬قرار مجلس الوزراء رقم‪ 11‬يف ‪1374/2/1‬هـ‬\n                    ‫‪ -2‬األمر السامي رقم ‪ 59633‬يف ‪1432/12/9‬هـ‪.‬‬\n    ‫‪ -3‬املادة الثالثة من قرار وزير الداخلية رقم ‪2057‬يف ‪1404/5/26‬هـ‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد االجتــار‬\n‫والهــروب مــن رجــال األمــن وطلــب إثبــات مــا أســند إليــه واحلكــم بتعزيره‬\n‫ومنعــه مــن الســفر وتعزيــره لقــاء هروبــه مــن رجــال األمــن ‪ ،‬وأثنــاء قيــام‬\n‫دوريــة املجاهديــن بحراســة احلــدود أقبلــت عليهــا ســيارة يقودهــا املدعــى‬\n‫عليــه فطلــب منــه التوقــف ولــم ميتثــل فتمــت مطاردتــه والقبــض عليــه‬\n‫وبتفتيــش الســيارة عثــر بهــا علــى كمية مــن نبات القات‪،‬وأثبــت التقرير‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‬\n‫‪،‬وصــادق املدعــى عليــه باالدعــاء املوجــه إليــه بنقــل القــات حلســاب الغيــر‬\n‫مقابــل مبلــغ مالــي لقصــد الترويــج حكمــت احملكمــة احلكــم بتعزيــره‬\n\n\n                                                                                      ‫‪302‬‬\n\f      ‫بالســجن خمــس ســنوات وجلــده خمســمائة جلــدة مفرقــة علــى دفعــات‬\n      ‫كل دفعــة خمســون و غرامــة ماليــة قدرهــا خمســة عشــر ألــف ريــال‬\n      ‫تــودع يف بيــت مــال املســلمني و صــرف النظــر عــن مطالبــة املدعــي العــام‬\n      ‫مبنعــه مــن الســفر خــارج البــاد لعــدم اشــتمال املــادة املعاقــب بهــا املدعــى‬\n      ‫عليــه ‪ ،‬قنــع املدعــى عليــه باحلكــم واعتــرض املدعــي العــام مكتفي ـ ًا‬\n                   ‫بالئحــة الدعــوى و صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34111631‬وتاريــخ ‪1434/03/08‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34586907‬وتاريــخ ‪1434/03/08‬ه ـ ففــي يــوم‬\n      ‫االثنني املوافق‪1434/03/09‬هـ افتتحت اجللســة الســاعة ‪ 09 : 15‬وفيها‬\n      ‫حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم(‪ ).....‬وتاريــخ ‪1433/3/22‬ه ـ‬\n      ‫واملدعــى عليــه ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪).....‬‬\n      ‫وقــدم املدعــي العــام دعــوى محــررة تتضمــن أنــه ‪ :‬بتاريــخ ‪1434/2/11‬هـ‬\n      ‫وأثنــاء قيــام إحــدى دوريــات املجاهدين بحراســة احلــدود واملواقع احملددة‬\n      ‫لهــا وأثنــاء جتولهــم يف مركــز ‪.....‬وحتديــدا علــى اخلــط املــؤدي مــن ‪.....‬‬\n      ‫للمثلــث املــؤدي مــن ‪ ......‬لصبيــا وبقريــة ‪.....‬أقبلــت عليهــم ســيارة مــن‬\n      ‫نــوع ‪....‬حتمــل اللوحــة رقــم (‪ ).....‬تعــود ملكيتــه للمدعــو ‪(..... /‬أعيــدت‬\n      ‫ملالكهــا) متجــه مــن جهــة ‪.....‬باجتــاه مثلــث ‪.....‬ومت التأشــير لــه بالوقــوف‬\n      ‫ولــم ميتثــل لذلــك وقــام بالرجــوع إلــى اخللــف ومت ابــاغ القيــادة ومت إبــاغ‬\n\n‫‪303‬‬\n\f‫العمليــات ومتــت مطاردتــه وقــد اجتــه يســار اخلــط ‪.....‬باجتــاه قريــة ‪.....‬ومت‬\n‫إطــاق طلقتــن حتذيريــة لغــرض إيقافــه وكانــت هنــاك ســيارة أخــرى‬\n‫مــن نــوع ‪ ....‬تضايــق الدوريــة ولــم تتمكــن الدوريــة مــن أخــذ لوحتهــا‬\n‫ومت القبــض علــى املدعــى عليــه وكانــت الســيارة بقيادتــه وبتفتيــش‬\n‫الســيارة عثــر بهــا علــى كميــة مــن نبــات القــات بلــغ وزنــه (‪133‬كجــم)‬\n‫مائــة وثالثــة وثالثــن كيلــو جرامـ ًا أثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم (‪.....‬بتاريــخ ‪1434/2/19‬ه ـ إيجابيــة العينــة املرســلة مــن الكميــة‬\n‫املضبوطــة لنبــات القــات احملظــور وباســتجواب املدعــى عليــه أقــر بنقلــه‬\n‫كميــة القــات املضبوطــة البالــغ وزنهــا (‪133‬كجــم) مائــة وثالثــة‬\n‫وثالثــن كيلــو جرامـ ًا مــن نبــات القــات احملظــور حيث ذكــر بأن هناك‬\n‫شــخصا ســيقابله بجــوار محطــة ‪.....‬ويقــوم مبتابعتــه إلــى مــكان إنــزال‬\n‫الكميــة مقابــل مبلــغ مالــي وقــدره (‪10‬ريــاالت) لــكل حبــة وقــد أســفر‬\n‫التحقيــق معــه عــن توجيــه االتهــام إليــه بنقــل مــا وزنــه (‪133‬كجــم) مائــة‬\n‫وثالثــة وثالثــن كيلــو جرامـ ًا مــن نبــات القــات احملظــور بقصــد االجتــار‬\n‫وهروبــه مــن رجــال األمــن وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء‬\n‫يف أقوالــه مبحضــر االســتجواب املرفــق ‪ -2‬مــا جــاء مبحضــر القبــض‬\n                                          ‫والتفتيــش املشــار لــه املرفــق بــاألوراق‬\n‫‪ -3‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق ‪ -4‬مــا‬\n‫جــاء مبحضــر القبــض هروبــه مــن رجــال األمــن وحيــث إن مــا أقــدم عليــه‬\n‫املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب قــرار مجلس‬\n‫الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا أطلب ما‬\n‫يلــي‪ -1 :‬إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة‬\n‫(الثالثــة) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذا لألمــر الســامي‬\n\n\n                                                                                         ‫‪304‬‬\n\f      ‫الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ ‪ -2‬منعــه مــن الســفر‬\n      ‫بعــد انتهــاء محكوميتــه اســتنادا لتعميــم وزيــر الداخليــة رقــم (‪)69935‬‬\n      ‫وتاريــخ ‪1433/6/18‬ه ـ ‪ -3‬تعزيــره شــرعا لقــاء هروبــه مــن رجــال األمــن‬\n      ‫وبســؤال املدعــى عليــه املذكــور أعــاه أجــاب باالعتــراف بنقــل مــا وزنــه‬\n      ‫مائــة وثالثــة وثالثــون كيلــو جرام ـ ًا مــن نبــات القــات احملظــور حلســاب‬\n      ‫الغيــر مقابــل مبلــغ مالــي هكــذا أجــاب املدعــى عليــه عنــد ذلــك جــرى‬\n      ‫منــا االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى محضــري الوزن‬\n      ‫والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى وبنــاء علــى مــا ذكــر مــن‬\n      ‫دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليــه ‪.....‬ســعودي اجلنســية‬\n      ‫باالعتــراف بنقــل مــا وزنــه مائــة وثالثــة وثالثــون كيلــو جرام ـ ًا حلســاب‬\n      ‫الغيــر مقابــل مبلــغ مالــي لــذا فقــد ثبــت لــدى شــرع ًا إدانــة املدعــى عليــه‬\n      ‫املذكــور بنقــل كميــة نبــات القــات احملظــور املوضحــة أعــاه حلســاب‬\n      ‫الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج وهــو يســتحق العقوبــة علــى‬\n      ‫ذلــك وفــق املــادة الثالثــة مــن قــرار ســمو وزيــر الداخليــة رقــم ‪2057‬‬\n      ‫وتاريــخ ‪1404/5/26‬ه ـ اســتنادا لقــرار مجلــس الــوزراء رقــم ‪ 11‬وتاريــخ‬\n      ‫‪1374/2/1‬ه ـ إنفــاذ ًا لألمــر الســامي الكــرمي رقــم ‪ 59633‬وتاريــخ‬\n      ‫‪1432/12/9‬ه ـ وملــا ذكــر أعــاه فقــد حكمــت بتعزيــره بالســجن ملــدة‬\n      ‫خمــس ســنوات مــن تاريــخ إيقافــه يف ‪1434/2/11‬ه ـ وجلــده بخمســمائة‬\n      ‫جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون جلــدة بــن الدفعــة واألخــرى‬\n      ‫عشــرة أيــام وغرامــه ماليــة قدرهــا خمســة عشــر ألــف ريــال تــودع بيــت‬\n      ‫مــال املســلمني وصرفــت النظــر عــن مطالبــة املدعــي العــام مبنــع املدعــى‬\n      ‫عليــه مــن الســفر خــارج البــاد لعــدم اشــتمال املــادة املعاقــب بهــا املدعــى‬\n      ‫عليــه لذلــك واكتفــاء بالعقوبــة الصــادرة بحــق املدعــى عليــه أعــاه هــذا‬\n\n\n‫‪305‬‬\n\f‫مــا حكمــت بــه وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫وطلــب املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة االدعــاء العــام‬\n‫وأمــرت بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة االســتئناف‬\n‫مبنطقــة عســير لدراســته وإبــداء مــا تــراه نحــوه وصلــى اهلل وســلم علــى‬\n                 ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/3/9‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بجازان برقــم ‪34586907‬‬\n‫وتاريــخ ‪1434/3/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n‫باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 3460741‬وتاريــخ ‪1434/3/11‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ...../‬يف قضيــة (قــات) علــى الصفــة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪306‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":302,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c070a1dca5269b2b4474468ea4685375172cb5aafd79b9605d703ba07edf5a97","normalized_text_hash":"7a898e95d01df899f2d22d388b810c90106d946161597fd2f49207fc31723c66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p302-3460741"},{"id":"21f3d179-5859-5a5d-837d-29d03df2f929","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة بقصد اإلجتار -تعاطي احلشيش املخدر -اإلقرار -مصادرة السيارة -إقامة حد املسكر على متعاطي احلشيش -تعزير املدعي عليه بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ احلكومي.","document_number":"34171068","case_number":"34126420","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/24","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة بقصد اإلجتار -تعاطي احلشيش املخدر -اإلقرار -مصادرة السيارة -إقامة حد املسكر على متعاطي احلشيش -تعزير املدعي عليه بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ احلكومي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34171068:‬تاريخه ‪1434/03/24:‬هـ‬\n                        ‫رقم الدعوى ‪34126420:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34212596‬تاريخه‪1434/05/13:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة بقصــد اإلجتــار ‪ -‬تعاطــي‬\n      ‫احلشــيش املخــدر ‪ -‬اإلقــرار‪ -‬مصــادرة الســيارة ‪ -‬إقامــة حــد املســكر علــى‬\n      ‫متعاطــي احلشــيش ‪ -‬تعزيــر املدعــي عليــه بالســجن واجللــد والغرامــة‬\n                         ‫واملنــع مــن الســفر واملصــادرة وإعــادة املبلــغ احلكومــي‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ‪( :‬يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واالنصــاب‬\n           ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون)‪.‬‬\n                    ‫‪ -2‬قوله تعالى ‪( :‬والتفسدو ا يف االرض بعد اصالحها)‪.‬‬\n      ‫‪ -3‬املــواد (‪ )2/3‬و (‪ )1/38‬و (‪ )1/56‬و (‪ )1/53‬مــن نظــام مكافحــة‬\n                                                  ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج عــدد مــن حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة وتعاطــي احلشــيش‪ ،‬وطلــب املدعــي‬\n      ‫العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واجللــد والغرامــة واملنــع مــن الســفر وإقامــة حــد املســكر عليــه لتعاطيــه‬\n      ‫احلشــيش املخــدر‪ ،‬حيــث وردت معلومــات ملكافحــة املخــدرات مــن أحــد‬\n      ‫مصادرهــا عــن قيــام املدعــى عليــه بترويــج احلشــيش املخــدر واحلبــوب‬\n\n‫‪307‬‬\n\f‫احملظــورة ومت متكــن املصــدر مــن االتصــال علــى املدعــى عليــه علــى‬\n‫مســمع مــن أفــراد الفرقــة القابضــة و مت االتفــاق علــى شــراء عــدد مــن‬\n‫احلبــوب احملظــورة‪ ،‬مت تفتيــش املصــدر وتزويــده باملبلــغ احلكومــي‬\n‫املرقــم و تكليــف أحــد أفــراد الفرقــة مبرافقتــه ويف املــكان احملــدد‬\n‫حضــر املدعــي عليــه بســيارته ومتــت عمليــة االســتالم والتســليم‪ ،‬غــادر‬\n‫املدعــى عليــه املوقــع مســرع ًا و اختفــى عــن األنظــار ومت التعميــم عليــه‬\n‫وبعــد شــهرين ونصــف تقريبـ ًا مت القبــض عليــه مــن قبــل جــوازات جســر‬\n‫امللــك فهــد‪ ،‬كمــا أقــر املدعــي عليــه مبــا نســب إليــه‪ ،‬بنــاء علــى مــا تقدم‬\n‫صــدر احلكــم بإثبــات إدانــة املدعــى عليــه مبــا نســب إليــه و احلكــم‬\n‫عليــه بإقامــة حــد املســكر وتعزيــره بالســجن واجللــد والغرامــة واملنــع مــن‬\n‫الســفر ومصــادرة الســيارة و الهاتــف اجلــوال وإعــادة املبلــغ احلكومــي‬\n                                 ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n‫برقــم وتاريــخ ‪1434/3/16‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ‬\n‫‪1434/3/16‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ ..... /‬ضد ‪ ، .... /‬حامل‬\n‫الســجل املدنــي رقــم (‪ ).....‬ففــي يــوم الثالثــاء ‪1434/ 3 / 24‬ه ـ فتحــت‬\n‫اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n‫يلــي ‪( :‬بصفتــي مدعيـ ًا عامــا يف دائــرة التحقيــق واالدعاء العام مبحافظة‬\n‫القطيــف أدعــي علــى ‪ ، .... :‬البالــغ مــن العمــر (‪ ،)26‬ســعودي اجلنســية‬\n\n                                                                                        ‫‪308‬‬\n\f      ‫مبوجــب الســجل املدنــي رقــم (‪ ،).....‬غيــر محصــن ‪ ،‬موظــف أهلــي ‪،‬‬\n      ‫قبــض عليــه بتاريــخ ‪1409/8/14‬ه ـ ‪ ،‬وأحيــل إلــى ســجن محافظــة‬\n      ‫القطيــف اســتنادا للقــرار الــوزاري رقــم (……) بتاريــخ ‪1428/7/9‬هــ‪.‬‬\n      ‫حيــث أنــه بتاريــخ ‪1433/11/8‬ه ـ وردت معلومــات لرجــال مكافحــة‬\n      ‫املخــدرات بالدمــام مــن أحــد مصادرهــم الســرية عــن قيــام املدعــى عليــه‬\n      ‫بترويــج احلشــيش املخــدر واحلبــوب احملظــورة‪ ،‬فتــم متكينــه مــن االتصال‬\n      ‫علــى جــوال املدعــى عليــه رقــم (‪ ).....‬ورقمــه املصنعــي (‪ ،).....‬وطلــب منــه‬\n      ‫خمســا وعشــرين حبــة مــن احلبــوب احملظــورة‪ ،‬فأجابــه باملوافقــة‬  ‫ً‬      ‫(‪)25‬‬\n      ‫وأن قيمتهــا (‪ )600‬ســت مائــة ريــال وحــدد مــكان التســليم علــى طريــق‬\n      ‫صفــوى ‪ -‬وكانــت املكاملــة علــى مســمع مــن أفــراد الفرقــة القابضــة‪،‬‬\n      ‫فجــرى تفتيــش املصــدر وتكليــف أحــد أفــراد الفرقــة القابضــة‬\n      ‫مبرافقتــه وتزويــد املرافــق باملبلــغ املرقــم وقــدره (‪ )600‬ســت مئــة ريــال‪،‬‬\n      ‫وبانتقالهــم للموقــع املتفــق عليــه حضــر املدعــى عليــه علــى ســيارة نــوع‬\n      ‫‪ .....‬لوحــة رقــم (‪ ).....‬وقــام باســتالم املبلــغ وغــادر املوقــع‪ ،‬وبعــد ربــع‬\n      ‫ســاعة عــاد وتوقــف بجانــب املصــدر ومرافقــه وســلم املصــدر (‪ )21‬واحــد‬\n      ‫وعشــرين حبــة اثبــت التقريــر الكيمــاوي الشــرعي رقــم (……‪ ).‬وتاريخ‬\n      ‫‪1433/11/8‬ه ـ ايجابيــة عينتهــا ملــادة االمفيتامــن املنبهــة احملظــورة ‪،‬‬\n      ‫وغــادر املوقــع مســرعا واختفــى عــن األنظــار فتــم التعميــم عليــه‪ .‬وبتاريــخ‬\n      ‫‪ 1434/1/22‬ه ـ قبــض علــى املدعــى عليــه مــن قبــل جــوازات جســر امللك‬\n      ‫فهــد‪ ،‬وبتاريــخ ‪1434/1/24‬ه ـ أودع التوقيــف مبكافحــة املخــدرات ‪،‬‬\n      ‫و جــرى التعــرف عليــه مــن قبــل أفــراد الفرقــة القابضــة واعــد محضــر ًا‬\n      ‫بذلــك‪ .‬وباســتجوابه أفــاد بــأن رقــم الهاتــف احملمــول (‪ ).....‬عائــد لــه‬\n      ‫يف الســابق وان ســيارته نــوع ‪ .....‬موديــل ‪ 93‬لوحــة رقــم (‪ ، ).....‬واقــر‬\n\n\n‫‪309‬‬\n\f‫بتعاطــي احلشــيش املخــدر منــذ ســنة وآخــر مــرة كانــت قبــل القبــض‬\n‫عليــه بيــوم ‪ .‬وقــد أســفر التحقيــق عــن اتهامــه ببيــع عــدد (‪ )21‬واحــد‬\n‫وعشــرين حبــة مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد االجتــار‬\n‫و تعاطــي احلشــيش املخــدر ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪-1 :‬مــا ورد‬\n‫باســتجوابه املنــوه عنــه املرفــق علــى اللفــات رقــم (‪-2 .)19-17‬محاضــر‬\n‫البــاغ و االتصــال و التعــرف و االنتقــال و الضبــط املنــوه عنهــا املدونــة‬\n‫علــى الصفحــات رقــم (‪ )13-12 ، 4 ، 2‬مــن ملــف التحقيــق‪-3 .‬التقريــر‬\n‫الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم(‪ . )7‬وبالبحــث‬\n‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجله‪ .‬وحيــث إن‬\n‫مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ ،‬فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب إثبــات مــا اســند إليــه‬\n‫وفــق الفقــرة رقــم(‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪.1 :‬بعقوبــة الســجن واجللــد‬\n‫والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم(‪ )38‬مــن النظــام‬\n‫‪،‬وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )62‬من ذات النظام ‪ ،‬والتشــديد‬\n‫عليــه كــون املــادة املروجــة حبــوب منبهــة وفــق الفقــرة (‪/2‬ج) مــن املــادة‬\n‫رقــم(‪ )38‬مــن النظــام‪ ،‬و اســتنادا لبرقيــة صاحــب الســمو امللكــي وزيــر‬\n‫الداخليــة رقــم(……………‪ ).‬وتاريــخ ‪1427/2/8‬ه ـ ‪.2 .‬منعــه مــن‬\n‫الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام املشــار‬\n‫اليــه‪.3 .‬مصــادرة جوالــه و ســيارته املوصوفــن بالوقائــع وفــق الفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬وعــدم صــرف شــريحة اجلــوال‬\n‫لنفــس املدعــى عليــه وفقـ ًا لتعميــم وزيــر الداخليــة رقــم (……………‪).‬‬\n‫وتاريــخ ‪1428/2/10-9‬ه ـ ‪-4 .‬إلزامــه بدفــع املبلــغ املرقــم الــذي لــم يتــم‬\n\n\n                                                                                     ‫‪310‬‬\n\f              ‫العثــور عليــه وفــق تعميــم وزيــر الداخليــة رقــم (‪)65980/4/5/1‬‬\n      ‫وتاريــخ ‪1428/10/23-22‬هــ‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى‬\n      ‫علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف الدعــوى كلــه صحيــح‬\n      ‫والســيارة املذكــورة يف الدعــوى عائــدة لــي وأنــا تائــب ونــادم وأطلــب مــن‬\n      ‫اهلل العفــو والصفــح هــذا جوابــي وبتصفــح املعاملــة وجــدت علــى اللفــة‬\n      ‫رقــم ‪ 7‬التقريــر الكيمــاوي رقــم ‪ 4052‬ك ش املتضمــن ‪ ( :‬إيجابيــة‬\n      ‫العينــة ملــادة االمفيتامــن ) ا‪.‬ه ـ فبنــاء علــى مــا تقدم من الدعــوى واإلجابة‬\n      ‫وحيــث أقــر املدعــى عليــه مبــا نســب إليــه ولقولــه تعالــى ‪ ( :‬يــا أيهــا الذيــن‬\n      ‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n      ‫فاجتنبــوه لعلكــم تفلحــون ) وقولــه ( وال تفســدوا يف األرض بعــد‬\n      ‫إصالحهــا ) وبنــاء علــى املــواد ‪ 2/3‬و ‪ 1/38‬و ‪ 1/56‬و ‪ 1/53‬مــن نظــام‬\n      ‫مكافحــة املخــدرات ولكــون املدعــى عليــه ليــس مــن أربــاب الســوابق‬\n      ‫وإلقــراره بذنبــه ومــا أبــداه مــن توبــة ممــا يخولــه االســتفادة مــن املــادة ‪60‬‬\n      ‫مــن النظــام فقــد حكمــت مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه ببيــع‬\n      ‫واحــد وعشــرين حبــة مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد‬\n      ‫االجتــار و تعاطــي احلشــيش املخــدر ‪-2‬جلــد املدعــى عليــه ثمانــن جلــدة‬\n      ‫حــد املســكر ‪-3‬تعزيــر املدعــى عليــه بســجن مــدة ثــاث ســنوات وجلــده‬\n      ‫خمســن جلــدة تتكــرر عليــه ســت مــرات وتغرميــه ألــف ريــال ومنعــه مــن‬\n      ‫الســفر بعــد خروجــه مــن الســجن مــدة ثــاث ســنوات ومصــادرة ســيارته‬\n      ‫املذكــورة يف الدعــوى ومصــادرة هاتفــه اجلــوال وعــدم صــرف نفــس‬\n      ‫الشــريحة لــه و إلزامــه بتســليم املبلــغ احلكومــي وقــدره ســتمائة ريــال‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم قناعتــه ورغبتــه‬\n      ‫رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وقــرر‬\n\n\n‫‪311‬‬\n\f‫املدعــى عليــه قناعتــه وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره يف‬\n                                                              ‫متــام الســاعة ‪. 11 : 45‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/6/12‬ه ـ فتحــت اجللســة‬\n‫يف متــام الســاعة ‪ 10 : 00‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم يف‬\n‫‪1434/5/13‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1434/6/12‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم‬\n‫وتاريــخ ‪1434/3/28‬ه ـ املقيــدة لــدى احملكمــة برقــم ………‬\n‫وتاريــخ ‪1434/4/7‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ...........‬املســجل برقــم وتاريــخ ‪1434/3/24‬ه ـ‬\n‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ ......... /‬يف قضيــة مخــدرات وقــد‬\n‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                            ‫حرريف‪1434/5/12‬ه ـ‬\n\n\n\n\n                                                                                          ‫‪312‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":307,"source_page_end":312,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f52df4531a8b028ce69c2f4b046cdf3de0b1a3e22d1089ef685395e889adaf58","normalized_text_hash":"892deaca29ec44496535fdf53e8c9f63831f0751dfe443787533e6a1759ac325","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p307-34171068"},{"id":"8ed987fc-6ad5-5aa0-875d-05b0323c7a14","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -تستر -توجيه شبهة -تعزير بالشبهة -تعزير بالتهمة -تعزير بالسجن واجللد -تعزير باملصادرة- تعزير بإلغاء شريحة جوال -تسليم حبوب محظورة -استالم حبوب","document_number":"34232696","case_number":"34161758","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/6","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -تستر -توجيه شبهة -تعزير بالشبهة -تعزير بالتهمة -تعزير بالسجن واجللد -تعزير باملصادرة- تعزير بإلغاء شريحة جوال -تسليم حبوب محظورة -استالم حبوب","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34232696:‬تاريخه ‪1434/6/6:‬هـ‬\n                        ‫رقم الدعوى ‪34161758:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34273141‬تاريخه‪1434/07/19:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة‪ -‬تســتر‪ -‬توجيــه شــبهة‪ -‬تعزيــر‬\n      ‫بالشــبهة‪ -‬تعزير بالتهمة‪ -‬تعزير بالســجن واجللد ‪ -‬تعزير باملصادرة‪-‬‬\n      ‫تعزيــر بإلغــاء شــريحة جــوال‪ -‬تســليم حبــوب محظــورة‪ -‬اســتالم حبــوب‬\n                                                                    ‫محظــورة‬\n\n\n\n\n                       ‫املادة ‪ 53‬من نظام مكافحة املخدرات و املؤثرات العقلية‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتوجيــه االتهــام لــه بترويــج‬\n      ‫حبــوب اإلمفيتامــن وتســتره علــى املصــدر الــذي حصــل منــه علــى‬\n      ‫احلبــوب احملظــورة ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه و احلكــم‬\n      ‫عليــه بالســجن واجللــد والغرامــة و منعــه مــن الســفر بعــد انتهــاء عقوبتــه و‬\n      ‫تعزيــره لقــاء تســتره علــى مصــدر مــا ضبــط و مصــادرة الهاتــف اجلــوال و‬\n      ‫إلغــاء الشــريحة و التــزام املدعــى عليــه بــرد املبلــغ املرقــم ‪ ،‬حيــث أنــه مت‬\n      ‫القبــض علــى املدعــى عليــه بعــد ورود معلومــات ســرية لــدى املكافحــة‬\n      ‫تفيــد بوجــود شــخص يقــوم بالتوســط يف ترويــج احلبــوب احملظــورة و‬\n      ‫يتواجــد علــى جوالــه و اســتعد املصــدر بالشــراء املباشــر مــن املــروج و‬\n      ‫مت متكــن املصــدر مــن االتصــال بهاتــف جــوال املعنــي باإلخباريــة و‬\n\n‫‪313‬‬\n\f‫طلــب منــه كميــة حبــوب مقابــل مبلــغ مالــي فأبــدى املتهــم موافقتــه‬\n‫وطلــب منــه احلضــور وعندهــا مت تزويــد املصــدر مببلــغ مرقــم ومت‬\n‫تفتيــش املصــدر تفتيشـ ًا دقيقـ ًا وجــرى تكليــف أحــد أفــراد املكافحــة‬\n‫مبرافقــة املصــدر ملشــاهدة عمليــة االســتالم والتســليم وحضــر املتهــم و‬\n‫قابــل املصــدر يف املــكان املتفــق عليــه وســلم املصــدر للمتهــم مبلــغ مالــي‬\n‫مرقــم ثــم غــادر املتهــم نصــف ســاعة ثــم حضــر وســلم للفــرد املكلــف‬\n‫بالشــراء أربــع حبــات يشــتبه أن تكــون احلبــوب احملظــورة‪ ،‬كمــا أنكر‬\n‫املدعــى عليــه الدعــوى‪ ،‬إحضــار املدعــى العــام البينــة غيــر مكتملــة‪،‬‬\n‫بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن‬\n‫واجللــد ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة وإدخــال قيمتــه يف‬\n‫حســاب مكافحــة املخــدرات وإلغــاء الشــريحة املضبوطــة وعــدم صرفها‬\n               ‫للمدعــى عليــه وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34161758‬وتاريــخ‬\n‫‪ 1434/04/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34860652‬وتاريــخ‬\n‫‪ 1434/04/08‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/04/13‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 09 : 45‬وفيهــا حضــر املدعــي العــام ‪ ..............‬مبوجــب‬\n‫خطــاب التكليــف مــن مرجعــه رقــم ‪ ..............‬يف ‪1434/1/24‬هـ وادعى‬\n‫علــى احلاضــر ‪ : ..................... /‬ســعودي بالســجل املدنــي ‪....................‬‬\n‫حيــث انــه بتاريــخ ‪1434/1/14‬ه ـ وردت معلومــات ســريه لدى مكافحة‬\n\n                                                                                          ‫‪314‬‬\n\f      ‫املخــدرات بالعاصمــة املقدســة تفيــد عــن وجــود شــخص يقــوم يف‬\n      ‫بالتوســط يف ترويــج احلبــوب احملظــورة بشــارع ‪ ..............‬حــارة ‪..............‬‬\n      ‫ويتواجــد علــى رقــم جــوال (‪ )..............‬واســتعد املصــدر بالشــراء املباشــر‬\n      ‫مــن املــروج ومت متكــن املصــدر مــن االتصــال بهاتــف جــوال املعنــي‬\n      ‫باإلخباريــة وطلــب منــه كميــة مــن احلبــوب احملظــورة مببلغ وقــدره(‪)100‬‬\n      ‫مائــة ريــال فأبــدى املعنــي باإلخباريــة موافقتــه وطلــب منــه احلضــور إليــه‬\n      ‫بشــارع ‪ ..............‬عندهــا مت تزويــد املصــدر مببلــغ مرقــم وقــدره(‪)100‬‬\n      ‫مائــة ريــال بعــد تفتيشــه تفتيشــا دقيقــا ودفعــه حتــت أنظــار الفرقــة‬\n      ‫وجــرى تكليــف الفــرد رقــم (‪ )..............‬مبرافقــة املصــدر ملشــاهدة‬\n      ‫عمليــة االســتالم والتســليم ومت دفــع املصــدر والفــرد إلــى املوقــع احملــدد‬\n      ‫مــن قبــل الوســيط ومت مشــاهدت املعنــي باإلخباريــة مترجل علــى األقدام‬\n      ‫واســتلم املبلــغ مــن املصــدر واختفــى عــن األنظــار ملــدة نصــف ســاعة‬\n      ‫وبعدهــا حضــر وأســتلم املصــدر والفــرد املكلــف بــدور املشــتري عــدد‬\n      ‫(‪ )4‬أربعــة حبــات يشــتبه أن تكــون مــن حبــوب الكبتاجــون احملظــورة‬\n      ‫ومت مشــاهدت املعنــي باإلخباريــة علــى ســيارة مــن نــوع ‪ ....‬ومت القبــض‬\n      ‫عليــه واتضــح انــه املدعــى عليــه وعثــر معــه علــى جهــاز اجلــوال الــذي مت‬\n      ‫التنســيق عليــه يف عمليــة الشــراء واتضــح أنــه ويحمــل الرقــم املصنعــي‬\n      ‫(‪ )..............‬ولــم يعثــر معــه علــى املبلــغ احلكومــي املرقــم‪،‬ومت التعــرف‬\n      ‫عليــه مــن قبــل الفــرد مت حجــز املضبوطــات جهــاز اجلــوال املســتخدم‬\n      ‫يف اجلرميــة وباســتجواب املدعــى عليــه أفــاد بــان اجلــوال الــذي يحمــل‬\n      ‫الرقــم املصنعــي (‪ )..............‬والشــريحة رقــم (‪ )..............‬عائــد لــه وحتــت‬\n      ‫تصرفــه شــخص ًا وقــد اثبــت التقريــر الكيميائــي الشــرعي (‪..............‬ـ)‬\n      ‫ايجابيــة املــادة املروجــة املضبوطــة ملــادة االمفيتامني احملظــورة واملدرجة‬\n\n\n‫‪315‬‬\n\f‫باجلــدول رقــم (‪ )2‬فئــه (ب) امللحــق بنظــام مكافحة املخدرات واملؤثرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بترويــج (‪ )4‬أربــع‬\n‫حبــات مــن احلبــوب حتتــوي علــى مــادة االمفيتامــن عــن طريــق البيــع‬\n‫احملــرم شــرع ًا واملجــرم نظامـ ًا وفقـ ًا للفقــرة( الثانيــة) مــن املــادة( الثالثــة)‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي الكــرمي رقــم (م‪ )39/‬يف ‪1426/7/8‬ه ـ وتســتره علــى املصــدرة‬\n‫الــذي حصــل منــه علــى احلبــوب احملظــورة وذلــك لألدلــة والقرائــن التاليــة‬\n‫ا يف محضــر‬     ‫‪ -1‬مــاورد يف محضــر القبــض والتفتيــش املنــوه عنــه تفصيـ ً‬\n                                 ‫االســتدالل املرفــق بالقضيــة لفــه (‪ )1‬ص (‪)12‬‬\n‫‪ -2‬مــاورد بالتقريــر الكيميائــي الشــرعي املرفــق بالقضيــة لفــه( ‪)17‬‬\n‫وحيــث إن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا مبوجــب‬\n‫نظــام مكافحــة املخــدرات الصــادر باملرســوم امللكــي رقــم(م‪)39/‬‬\n‫بتاريــخ ‪1426/7/8‬ه ـ املشــار إليــه بعقوبتــه األصليــة والتكميليــة لــذا‬\n‫أطلــب إثبــات أدانتــه مبــا أســند إليــه واحلكــم عليــه بالعقوبــات التاليــة‬\n‫‪-1‬بالســجن واجللــد والغرامــة لقــاء ماأســند إليــه وفق ـ ًا للفقــرة(‪)1‬‬\n‫مــن املــادة (‪)38‬مــن نظــام املخــدرات واملؤثــرات العقليــة وأن تكــون‬\n‫عقوبتــه بحدهــا األعلــى لقــاء ترويجــه للحبــوب احملظــورة وفقـ ًا لتعميــم‬\n‫صاحــب الســمو امللكــي ولــي العهــد وزيــر الداخليــة رقــم(‪)8346‬‬\n‫تاريخ‪1427/2/10-9‬هـ‪-2..‬منعــه مــن الســفر خلــارج البــاد بعــد أنتهــا‬\n‫تنفيــذ عقوبتــه وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n‫املخــدرات املشــار إليــه ‪-3‬تعزيــرة لقــاء تســتره علــى مصــدرة يف احلصــول‬\n\n\n                                                                                              ‫‪316‬‬\n\f      ‫علــى املــواد احملظــورة وفقـ ًا لتعميــم معالــي رئيــس الهيئــة رقــم( ‪)15596‬‬\n                                                               ‫تاريــخ ‪1433/5/4‬هــ‪.‬‬\n      ‫‪-4‬مصــادرة الهاتــف اجلــوال ذو الرقــم املصنعــي (‪ )..............‬للشــريحة‬\n      ‫رقــم (‪ )..............‬وفق ـ ًا للفقــرة األولــى مــن املــادة رقــم (‪ )53‬مــن نفــس‬\n      ‫النظــام والنــص يف القــرار الشــرعي علــى إدخــال قيمتــه ملؤسســة النقــد‬\n      ‫العربــي الســعودي حلســاب املديريــة العامــة ملكافحــة املخــدرات اســتناد ٍا‬\n      ‫لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )40656‬وتاريــخ‬\n      ‫‪1430/6/23‬ه ـ وإلغــاء الشــريحة وفقـ ًا لتعميــم ســمو النائــب الثاني وزير‬\n                               ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10 -9‬هــ‪.‬‬\n      ‫‪-5‬إلــزام املدعــى عليــه بــرد املبلــغ املرقــم قــدره(‪ )100‬ريــال إلدارة‬\n      ‫مكافحة املخدرات بالعاصمة املقدســة اســتناد ًا لتعميم وزير الداخلية‬\n             ‫رقــم ‪ 65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه اجــاب بقولــه ماذكــره املدعــي العــام غيــر صحيح‬\n      ‫ولــم أروج املخــدرات ولــم أســلم ولــم أســتلم شــيئا هــذه إجابتــي وقــال‬\n      ‫املدعــي العــام الصحيــح ماذكــرت ولــدي البينــة ســأحضرها يف اجللســة‬\n      ‫القادمــة لــذا رفعــت اجللســة ويف يــوم االحــد املوافــق ‪1434/4/21‬ه ـ‬\n      ‫افتتحــت اجللســة وحضــر فيهــا املدعــي العــام واملدعــى عليــه ولــم يحضــر‬\n      ‫املدعــي العــام بينتــه لــذا رفعــت اجللســة حلــن احضارهــا ويف يــوم اإلثنــن‬\n      ‫املوافق‪1434/05/27‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا حضــر‬\n      ‫املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه أحضــر‬\n      ‫للشــهادة ‪..............‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪..............‬‬\n      ‫فشــهد بقولــه انــه مت االتصــال علــى املدعــى عليــه وســمعته يوافــق‬\n      ‫صراحــة علــى بيــع حبــوب االمفيتامــن احملظــورة مبائــة ريــال وطلــب مــن‬\n\n\n‫‪317‬‬\n\f‫املصــدر احلضــور إليــه يف شــارع ‪..............‬فتوجــه املصــدر وزميلــه الــى‬\n‫املوقــع وانتهــت مهمتــي عنــد ذلــك هــذه شــهادتي كمــا حضــر للشــهادة‬\n‫‪..............‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪..............‬فشــهد بقولــه‬\n‫انــه مت االتصــال علــى املدعــى عليــه وســمعته يوافــق صراحــة علــى بيــع‬\n‫حبــوب اإلمفيتامــن احملظــورة مبائــة ريــال وطلــب مــن املصــدر احلضــور‬\n‫اليــه يف شــارع ‪..............‬فرافقــت املصــدر وقابلنــا املدعــى عليــه ورأيــت‬\n‫املصــدر يســلم املدعــى عليــه مائــة ريــال ثــم غــاب املدعــى عليــه قليــا‬\n‫ورجــع وســلم املصــدر اربــع حبــات إمفيتامــن وكان احلــي مكشــوفا فلم‬\n‫يشــاهده غيــري هــذه شــهادتي وقــال املدعــى عليــه مــا ذكــره الشــهود‬\n‫غيــر صحيــح وال اعرفهــم ثــم جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫املرفــق باملعاملــة لفــة ‪ 17‬فوجدتــه يتضمــن احتــواء املضبوطــات علــى‬\n‫اإلمفيتامــن احملظــور كمــا لــم أجــد للمدعــى عليــه ســوابق فرفعــت‬\n‫اجللســة للتأمــل ويف يــوم االثنــن املوافــق ‪1434/6/5‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد جــرى تأمــل القضيــة‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلــى إنــكار املدعــى عليــه‬\n‫لدعــوى املدعــي العــام وبنــاء علــى شــهادة البينــة العادلــة لســبق تزكيتهــم‬\n‫يف شــهادة ســابقة وحيــث لــم تكتمــل البينــة علــى الترويــج ألنــه لــم‬\n‫يشــاهد عمليــة الترويــج والتســليم واالســتالم ســوى الشــاهد الثانــي فــا‬\n‫تنطبــق علــى املدعــى عليــه املــواد ‪38‬و‪ 56‬مــن نظــام مكافحــة املخــدرات‬\n‫ونظــرا الكتمــال البينــة علــى االتصــال وســماع املكاملــة ولصراحــة‬\n‫شــهادة الشــاهد الثانــي وبنــاء علــى املــادة ‪ 53‬مــن نظــام مكافحــة‬\n‫املخــدرات لــذا فــإن الشــبهة القويــة تتجــه للمدعــى عليــه بإدانتــه مبــا‬\n‫أســند إليــه مــن ترويــج أربــع حبــات مــن حبــوب اإلمفيتامــن احملظــورة‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫عــن طريــق البيــع وتســتره علــى مصــدر احلبــوب وحكمــت بتعزيــره علــى‬\n      ‫ذلــك بالســجن مــدة ســنة ونصــف ابتــداء مــن تاريــخ التوقيــف وجلــده مائــة‬\n      ‫وســتني جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة أربعــون جلــدة بــن‬\n      ‫كل دفعــة وأخــرى شــهر كمــا ثبــت لــدي إدانــة املدعــى عليــه باســتخدام‬\n      ‫هاتفــه اجلــوال املذكــور للترويــج وحكمــت مبصــادرة الهاتــف اجلــوال ذو‬\n      ‫الرقــم املصنعــي (‪ )..............‬للشــريحة رقــم (‪ )..............‬وإدخــال قيمتــه‬\n      ‫مبؤسســة النقــد العربــي الســعودي حلســاب املديريــة العامــة ملكافحــة‬\n      ‫املخــدرات وإلغــاء الشــريحة املضبوطــة وعــدم صرفهــا للمدعــى عليــه‬\n      ‫وصرفــت النظــر عمــا ســوى ذلــك وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫قنــع بــه وقــد عــارض املدعــي العــام وطلــب االســتئناف بالئحــة فأجيــب‬\n      ‫لطلبــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمد وآلــه وصحبه‪.‬‬\n                                                              ‫حــرر يف ‪1434/6/5‬هــ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد ثــم عــادة املعامة مــن محكمة االســتئناف وبرفقها‬\n      ‫القرار رقم ‪ 34273141‬يف ‪1434/7/19‬هـ املتضمن املوافقة والتصديق‬\n      ‫علــى احلكــم وبــاهلل التوفيــق ‪.‬قاضــي اســتئناف‪ ............../‬ختــم‪ .‬توقيــع‪.‬‬\n      ‫قاضــي اســتئناف‪............../‬ختم‪ .‬توقيــع‪ .‬رئيــس اســتئناف‪............../‬ختم‪.‬‬\n                             ‫توقيــع لــذا جــرى احلاقــه واثباته حــرر يف ‪1434/8/3‬هـ‬\n\n\n\n\n‫‪319‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":313,"source_page_end":319,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d50174ca71ae27907c7ab2410d23a7f4d74ff682774619c769d68ae910e2d30","normalized_text_hash":"0d9020090c11563fe05064f8d850106adabbf60a66096fc81b3c181ad6d53a68","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p313-34232696"},{"id":"dfebab59-e74a-5274-bcab-bb564cb5da12","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -تستر على مصدر الكمية - الهروب -املدعى عليه أجنبي -التعزير بالسجن واجللد واملصادرة والتوصية باإلبعاد .","document_number":"34184623","case_number":"34163865","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/10","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -تستر على مصدر الكمية - الهروب -املدعى عليه أجنبي -التعزير بالسجن واجللد واملصادرة والتوصية باإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34184623:‬تاريخه‪1434/04/10 :‬هـ‬\n                   ‫رقم الدعوى‪34163865:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34203510‬تاريخه‪1434/05/01:‬هـ‬\n\n\n‫مخــدرات ‪ -‬نقــل بقصــد الترويــج ‪ -‬قــات ‪ -‬تســتر علــى مصــدر الكميــة ‪-‬‬\n‫الهــروب ‪ -‬املدعــى عليــه أجنبــي ‪ -‬التعزيــر بالســجن واجللــد واملصــادرة‬\n                                                      ‫والتوصيــة باإلبعــاد ‪.‬‬\n\n\n\n‫‪ -1‬املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬يف ‪1374‬ه ـ املعــدل‬\n‫بقــراري وزيــر الداخليــة رقــم (‪ )2057‬لعــام ‪ 1404‬ه ـ ورقــم ‪ 3818‬لعــام‬\n                                                                      ‫‪1410‬هـ‪.‬‬\n‫‪-2‬األمــر الســامي الكــرمي رقــم (‪ )59633‬يف ‪1433/12/9‬ه ـ القاضــي‬\n ‫باســتثناء عقوبــات قضايــا القــات مــن نظــام مكافحــة املخــدرات‪.‬‬\n‫‪ -3‬تعميــم صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس‬\n             ‫الــوزراء وزيــر الداخليــة رقــم (‪ )9798‬يف ‪1428/2/10‬ه ـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد الترويــج‬\n‫وطلــب إثبــات مــا أســند إليــه وتعزيــره ‪ ،‬وتعزيــره لقــاء هروبــه ومصــادرة‬\n‫جوالــه مــع إلغــاء الشــريحتني ‪،‬حيــث لــم يتوقــف املدعــى عليــه عنــد نقطة‬\n‫التفتيــش فجــرت مطاردتــه والقبــض عليــه وبتفتيــش الســيارة ضبــط‬\n‫بداخلهــا كميــة مــن نبــات أخضــر يشــتبه بأنــه قــات وأثبــت التقريــر‬\n\n                                                                                    ‫‪320‬‬\n\f      ‫الكيمائــي الشــرعي إيجابيــة العينــة لنبــات القــات احملظــور وصــادق‬\n      ‫املدعــى عليــه علــى الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n      ‫عليــه بالســجن ثــاث ســنوات تعزيــرا وغرامــة ماليــة قدرهــا عشــرة آالف‬\n      ‫ريــال وجلــده خمســون جلــدة مفرقــة علــى دفعــات ومصــادرة اجلوالــن‬\n      ‫وإلغــاء شــرائحهما وإبعــاده مــن البــاد وقنــع املدعــى عليــه واعتــرض‬\n      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬  ‫املدعــي العــام بــدون الئحــة ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34163865‬وتاريــخ ‪ 1434/04/09‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34871500‬وتاريــخ ‪ 1434/04/09‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/04/10‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم ‪.....‬‬\n      ‫يف ‪1433/3/22‬ه ـ وادعــى علــى احلاضــر معــه الســجني ‪ ..... /‬ـ ـ البالـ ــغ‬\n      ‫م ـ ــن العمـ ــر ـ ـ (‪ )29‬عــامـ ـ ـ ـ ًا ـ ( أجنبــي اجلنســية) ـ ب ـمــوجـ ــب البطاقــة‬\n      ‫البديلـ ـ ــة رق ــم ( ‪ ).....‬وتاري ــخ ‪1434/2/26‬هـ الصــادرة مــن مكافح ــة‬\n      ‫املخـ ــدرات بصامطـ ــة ( متـ ــزوج ـ متعلم ـ عامل ) مودع بشعبـ ــة السجـ ــن‬\n      ‫الع ـ ــام بجـ ــازان ( قسـ ــم سجـ ــن أحـ ــد املســارحـ ـ ــة ) مبــوجـ ـ ــب أمـ ــر‬\n      ‫التمــديـ ـ ــد واإلحالـ ـ ــة قـ ــم ( ‪ ).....‬وتاريخ ‪1434/3/4‬هـ كون جرميته من‬\n      ‫اجلرائــم املوجبــة للتوقيــف اســتناد ًا للقــرار الــوزاري رقــم (‪ ) 1900‬وتاريــخ‬\n      ‫‪1428/7/9‬ه ـ ويعتبــر إيقافــه مــن تاريخ القبض عليه يف ‪1434/2/26‬هـ‬\n      ‫إنــه يف متــام الســاعة اخلامســة والنصــف مــن صبــاح يــوم الثالثــاء املوافــق‬\n\n‫‪321‬‬\n\f‫‪1434/2/26‬ه ـ وأثنــاء قيــام إحــدى دوريــات شــرطة صامطــة بواجبهــا‬\n‫وحتديــد ًا عنــد إشــارة ‪.....‬مت االشــتباه يف ســيارة قادمــة مــن الشــرق إلــى‬\n‫الغــرب مــن نــوع تويوتــا ســنة الصنــع ( ‪ 2011‬م ) حتمــل اللوحــة رقــم (‪).....‬‬\n‫تعــود ملكيتهــا للشــركة ‪ (.....‬لــم يوجــه لــه االتهــام لكــون الســيارة‬\n‫مســروقة ومعمــم عنهــا بتاريــخ ‪1434/2/23‬ه ـ ) جــرت املخاطبــة بذلــك‬\n‫بقيـ ـ ـ ــادة ( املدعــى عليــه ) وباســتيقافه رفــض التوقــف وجــرت مطاردتــه‬\n‫حتــى وصــل طريــق ‪.....‬ومت القبــض عليــه وبتفتيشــها ضبــط بداخلهــا‬\n‫كميــة مــن نبــات أخضــر يشــتبه أن تكــون مــن نبــات القــات احملظــور‬\n‫بلــغ وزنهــا ( ‪ 306‬كجــم ) ثالثمائــة وســتة كيلــو جرامـ ًا وضبــط معــه‬\n‫جــوال مــن نــوع يحمــل الرقــم املصنعــي رقــم ( ‪ ).....‬مــع شريحـ ـ ــة حتمـ ـ ــل‬\n‫الرقـ ـ ـ ــم ( ‪ ) .....‬وجـ ـ ــوال آخـ ـ ــر مــن ن ـ ــوع يحم ـ ـ ــل ال ــرقـ ـ ـ ـ ــم ( ‪ ).....‬مــع‬\n‫شــريحة ( ‪ ، ).....‬أثبــت التقريــر الكيميائــي الشــرعي رقــم ( ‪.....‬لعــام‬\n‫‪1434‬ه ـ ) الصــادر مــن مركــز الســموم والكيميــاء الشــرعية الطبيــة‬\n‫بجــازان إيجابيــة العينــة املرســلة مــن الكميــة املضبوطــة لنبــات القــات‬\n‫احملظــور املــدرج يف اجلــدول رقــم ( ‪ ) 4‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ .‬باســتجواب ( املدعــى عليــه) بعــد مواجهتــه بالتهمــة‬\n‫املنســوبة إليــه وبأقوالــه يف محضــر ســماع األقــوال أقــر بنقــل الكميــة‬\n‫البالــغ وزنهــا ( ‪306‬كجــم ) ثالثمائــة وســتة كيلــو جــرام مــن نبــات‬\n‫القــات احملظــور لشــخص اســمه ‪.....‬امللقــب ب‪ (.....‬متــت املخاطبــة بشــأنه)‬\n‫مــن بعــد نقطــة ‪.....‬إلــى ‪.....‬مببلــغ ( ‪ ) 500‬خمســمائة ريــال لــم يســتلمها‬\n‫وأنــه هــو الشــخص الــذي ســلمه الســيارة وأقــر باســتخدام جواليــه االثنني‬\n‫يف اجلرميــة وبهروبــه مــن رجــال األمــن للخــوف وبــأن الســابقة املوجــودة‬\n‫يف كــرت البصمــات تعــود لــه واالســم املذكــور فيهــا اســم مســتعار‬\n\n\n                                                                                                           ‫‪322‬‬\n\f      ‫لــه خلوفــه علــى معاملتــه ‪.‬وقــد أســفر التحقيــق مــع ( املدعـ ــى عليــه) عـ ــن‬\n      ‫توجيـ ــه االتهـ ــام إليــه بنقــل مــا وزنــه ( ‪ 306‬كجــم ) ثالثمائــة وســتة‬\n      ‫كيلــو جرام ـ ًا مــن نبــات القــات احملظــور بقصــد الترويــج ‪ ،‬املجــرم‬\n      ‫مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة وبتســتره علــى مصــدر الكميــة ومبحاولتــه الهــرب‬\n                                ‫مــن رجــال األمــن وذلــك لألدلــة والقرائــن التاليــة ‪:‬ـ‬\n      ‫‪1‬ـ مــا جــاء يف إقــراره املنــوه عنــه املــدون بدفتــر التحقيــق ص ( ‪ ) 4‬املرفــق‬\n                                                                            ‫لفــة رقــم ( ‪. ) 34‬‬\n      ‫‪ 2‬ـ محضــر القبــض والتفتيــش املنــوه عنــه مبلــف ضبــط إجــراءات‬\n                                  ‫االســتدالل ص ( ‪ ) 12‬املرفــق لفــة رقــم ( ‪. ) 1‬‬\n             ‫‪ 3‬ـ التقرير الكيميائي الشرعي املنوه عنه املرفق لفة رقم ( ‪. ) 25‬‬\n      ‫وبالبحــث عــن ســوابقه عثــر لــه علــى ســابقة واحــدة وهــي اعتــداء باســم‬\n      ‫‪ ....‬وحيــث إن مــا أقــدم عليــه ( املدعــى عليــه ) فعــل محــرم شــرع ًا‬\n      ‫ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم ( ‪ ) 11‬لعــام‬\n                                   ‫‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا أطلــب ‪:‬‬\n      ‫‪1‬ـ إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره علــى ضــوء املــادة (‬\n      ‫الثالثــة ) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي‬\n                               ‫الكــرمي رقــم ( ‪ ) 59633‬وتاريــخ ‪1432/12/9‬ه ـ ‪.‬‬\n            ‫‪2‬ـ احلكم بتعزيره شرع ًا لقاء هروبه من رجال األمن أثناء القبض ‪.‬‬\n              ‫‪3‬ـ احلكم مبصادرة جهاز جوال من نوع يحمل الرقم املصنعي رقم‬\n      ‫(‪ )......‬وجــوال آخــر مــن نــوع يحمــل الرق ـ ـ ـ ــم ( ‪ ).....‬مــع إلغــاء الشــريحتني‬\n      ‫حتمــان الرق ـ ـ ــم ( ‪ ) .....‬والرقــم ( ‪ ) .....‬العائــدة ( للمدعــى عليــه ) وعــدم‬\n      ‫صــرف تلــك الشــريحتني لــه اســتناد ًا لتعميــم صاحــب الســمو امللكــي‬\n\n\n‫‪323‬‬\n\f‫النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة ( رحمــه اهلل )‬\n‫رقــم ( ‪ ) 9798‬وتاريــخ ‪9‬ـ ‪1428/2/10‬ه ـ واهلل املوفــق وبعــرض مــا جــاء‬\n‫يف دعــوى املدعــي العــام علــى املدعــى عليــه صــادق علــى صحــة واقعــة‬\n‫القبــض وأنــه هــو مــن كان يقــود ســيارة مــن نــوع والتــي ضبطــت بهــا‬\n‫كميــة القــات والبالــغ وزنهــا( ‪ 306‬كجــم ) ثالثمائــة وســتة كيلــو‬\n‫جرامـ ًا مــن نبــات القــات احملظــور و أن قصــده نقــل الكميــة املضبوطــة‬\n‫لشــخص اســمه ‪.....‬امللقــب ب‪.....‬مــن بعــد نقطــة ‪.....‬إلــى ‪.....‬مببلــغ ( ‪)500‬‬\n‫خمســمائة ريــال لــم يســتلمها وأنــه هــو الشــخص الــذي ســلمه الســيارة‬\n‫وأقــر باســتخدام جواليــه االثنــن يف اجلرميــة وبهروبــه مــن رجــال األمــن‬\n‫للخــوف وبــأن الســابقة املوجــودة يف كــرت البصمــات تعــود لــه واالســم‬\n‫املذكــور فيهــا اســم مســتعار لــه خلوفــه علــى معاملتــه هكــذا أجــاب‬\n‫وباالطــاع علــى محضــر القبــض و التحقيــق وجــد مطابــق ملــا جــاء يف‬\n‫الئحــة الدعــوى وباالطــاع علــى التقريــر الكيميائــي لفــة رقــم (‪)25‬‬\n‫وجــد إيجابيــة العينــة املرســلة منــه ملــادة القــات احملظــور وباالطــاع علــى‬\n‫صحيفــة الســوابق عثــر لــه علــى ســابقة اعتــداء فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه بترويــج الكميــة أعــاه‬\n‫عــن طريــق النقــل مقابــل مبلــغ مالــي وحيــث إن مــا أقــدم عليــه فعــل‬\n‫محــرم ومعاقــب عليــه نظامـ ًا فقــد ثبــت لــدي إدانــة املدعــى عليــه بترويــج‬\n‫مــا وزنــه ( ‪ 306‬كجــم ) ثالثمائــة وســتة كيلــو جرامـ ًا مــن نبــات القــات‬\n‫احملظــور عــن طريــق النقــل مقابــل مبلــغ مالــي وحكمــت عليــه تعزيــر ًا‬\n‫بالســجن ملــدة ثــاث ســنوات اعتبــارا مــن تاريــخ توقيفــه وبغرامــة ماليــة‬\n‫قدرهــا عشــرة آالف ريــال اســتنادا للمــادة الثالثــة مــن قــرار مجلــس‬\n‫الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ املعــدل بقــراري وزيــر الداخليــة رقــم‬\n\n\n                                                                                      ‫‪324‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":320,"source_page_end":324,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3628b288564eea3c029f159a44af584aece658f8150c5a49530b29c179da9ac2","normalized_text_hash":"ba852f29cf68bcc61c354cb9473f3b8bf8774cf75bcf69d848b996f00fb5e089","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p320-34184623"},{"id":"d2fc31f6-c333-5af6-adb4-05e6fdbc6386","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حشيش مخدر -الوساطة يف ترويج حشيش مخدر -حيازة حشيش مخدر -تعاطي حشيش مخدر -تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -تعزير بعدم صرف شريحة جوال للمدعى عليه -إقامة حد املسكر .","document_number":"34196192","case_number":"34165739","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/23","year":"1434","subject":"مخدرات -ترويج حشيش مخدر -الوساطة يف ترويج حشيش مخدر -حيازة حشيش مخدر -تعاطي حشيش مخدر -تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -تعزير بعدم صرف شريحة جوال للمدعى عليه -إقامة حد املسكر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34196192 :‬تاريخه ‪1434/04/23 :‬هـ‬\n                          ‫رقم الدعوى‪34165739 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34223687‬تاريخه‪1434/05/27 :‬هـ‬\n\n\n       ‫مخدرات ‪ -‬ترويج حشــيش مخدر ‪ -‬الوســاطة يف ترويج حشــيش مخدر‬\n       ‫‪ -‬حيــازة حشــيش مخــدر ‪ -‬تعاطــي حشــيش مخــدر ‪ -‬تعزيــر بالســجن‬\n       ‫واجللــد والغرامــة ‪ -‬تعزيــر باملنــع مــن الســفر ‪ -‬تعزير باملصــادرة ‪ -‬تعزير‬\n            ‫بعــدم صــرف شــريحة جــوال للمدعــى عليــه ‪ -‬إقامــة حــد املســكر ‪.‬‬\n\n\n\n\n       ‫‪ -1‬الفقــرة ‪ 2‬مــن املــادة ‪ 3‬والفقــرة ‪ 1‬مــن املــادة ‪ 38‬والفقــرة ‪ 1‬مــن املــادة‬\n       ‫‪ 53‬والفقــرة ‪ 1‬مــن املــادة ‪ 56‬و الفقــرة ‪ 1‬مــن املــادة ‪ 60‬والفقــرة ‪ 1‬مــن‬\n                      ‫املــادة ‪ 62‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n       ‫‪ -2‬ذكــر شــيخ اإلســام ابــن تيميــة يف الفتــاوى ( والصحيــح إن‬\n       ‫احلشيشــة مســكرة كالشــراب وان آكلهــا يحــد منهــا فهــي خمــر )‪-‬ج‪29‬‬\n                                                                                  ‫ص ‪135‬‬\n       ‫‪-3‬ذكــر شــيخ اإلســام بــن تيميــة رحمــه اهلل ( وفيهــا مــن املفاســد مــا‬\n       ‫ليــس يف اخلمــر وإن كان يف اخلمــر مفســدة ليســت فيهــا وهــي احلــدة‬\n       ‫فهــي بالتحــرمي أولــى مــن اخلمــر ألن ضــرر آكل احلشــيش علــى نفســه‬\n       ‫أشــد مــن ضــرر اخلمــر وضــرر شــارب اخلمــر علــى النــاس أشــد إال أنــه‬\n       ‫يف هــذه األزمــان لكثــرة آكل احلشــيش صــار الضــرر الــذي فيهــا علــى‬\n                                ‫النــاس أعظــم مــن اخلمــر ) الفتــاوى ج‪ 29‬ص ‪135‬‬\n\n\n\n‫‪327‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا باتهامهــا ببيــع األول للحشــيش‬\n‫املخــدر بقصــد االجتــار ‪ ،‬وتوســط املتهــم الثانــي يف بيــع احلشــيش املخــدر‬\n‫بقصــد االجتــار وحيــازة األول للحشــيش املخــدر بقصــد التعاطــي‬\n‫والترويــج وتعاطيهمــا للحشــيش املخــدر وطلــب املدعــي العــام إثبــات‬\n‫إدانتهمــا مبــا أســند إليهمــا و احلكــم عليهمــا بالعقوبــة الــورادة بالفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة‬\n‫املخــدرات و املؤثــرات العقليــة ومنعهمــا مــن الســفر ومصــادرة الهاتــف‬\n‫اجلــوال العائــد للمدعــى عليــه األول و الهاتــف اجلــوال العائــد للمدعــى‬\n‫عليــه الثانــي الســتخدامهما يف الترويــج و إســقاط شــريحة الهاتفــن و‬\n‫عــدم صرفهمــا لنفــس املتهمــن ‪،‬حيــث أنــه مت القبــض علــى املدعــى‬\n‫عليهمــا بعــد توفــر معلومــات مفادهــا عــن وجــود شــخص (املدعــى عليــه‬\n‫الثانــي) لــه نشــاط يف ترويــج احلشــيش املخــدر ألحــد أعوانــه واســتعد‬\n‫املصــدر باالطاحــة بــه باجلــرم املشــهود فتــم مراقبــة املــروج و الوســيط ومت‬\n‫مشــاهدتهما يتقابلــون مــع أشــخاص مشــبوهني و قــام املصــدر باالتصــال‬\n‫علــى الوســيط املدعــى عليــه الثانــي وكانــت املكاملــة علــى مســمع مــن‬\n‫أفــراد الفرقــة القابضــة و طلــب منــه قطعــة حشــيش فدلــه علــى أحــد‬\n‫أعوانــه املتهــم املدعــى عليــه األول وقــام بإرســال رقــم هاتفــه للمصــدر‬\n‫فتــم االتصــال عليــه و أخبــره املصــدر بأنــه عــن طريــق املدعــى عليــه‬\n‫الثانــي فرحــب بــه و طلــب املصــدر منــه قطعــة حشــيش مببلــغ قــدره مائتــا‬\n‫ريــال فوافــق وحــدد مــكان االســتالم و التســليم ومت تفتيــش املصــدر‬\n‫تفتيشـ ًا دقيقـ ًا و مت ترقيــم املبلــغ احلكومــي وقــام أحــد األفــراد مبرافقــة‬\n\n                                                                                      ‫‪328‬‬\n\f      ‫املصــدر و مشــاهدة عمليــة الترويــج حيــث قــام بتســليم املصــدر قطعــة‬\n      ‫ســمراء اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر فتــم القبــض عليــه‬\n      ‫و بتفتيشــه عثــر معــه علــى اجلــوال الــذي مت التنســيق معــه و أقــر أمــام‬\n      ‫الفرقــة القابضــة بــأن لديــه باملنــزل حشــيش مخــدر وباالنتقــال للمنــزل‬\n      ‫عثــر باملجلــس علــى املبلــغ احلكومــي و علــى قطعــة ســمراء اللــون يشــتبه‬\n      ‫أن تكــون مــن احلشــيش املخــدر و كذلــك عثــر علــى ســيجارة ملفوفــه‬\n      ‫يشــتبه أن تكــون ممزوجــة باحلشــيش املخــدر كمــا مت القبــض علــى‬\n      ‫الوســيط املدعــى عليــه األول و بتفتيــش ســيارته عثــر علــى عــدد خمــس‬\n      ‫قطــع يشــتبه أن تكــون مــن احلشــيش املخــدر و علــى مســدس و اجلــوال‬\n      ‫املســتخدم يف اجلرميــة و قــد أثبــت التقريــر الكيميائــي إيجابيــة العينــات‬\n      ‫املرســلة ملــادة احلشــيش املخــدر ‪ ،‬كمــا أقــر املدعــى عليهمــا بالدعــوى‪،‬‬\n      ‫بنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامــة حــد املســكر عليهمــا‬\n      ‫وتعزيرهمــا بالســجن واجللــد واملنــع مــن الســفر ومصــادرة اجلــوالت‬\n      ‫والشــرائح املســتخدمة يف اجلرائــم وصــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 34883199‬وتاريــخ ‪1434/4/10‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 34165739‬وتاريــخ ‪1434/4/10‬ه ـ‬\n      ‫افتتحــت اجللســة يف يــوم الســبت ‪1434/4/20‬ه ـ الســاعة الثانيــة عشــرة‬\n\n‫‪329‬‬\n\f‫والنصــف وفيهــا قــدم املدعــي العــام ‪ .....‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي‬\n‫مدعي ًا عام ًا بدائرة اإلدعاء العام لفرع املنطقة الشــرقية أدعي على كل‬\n‫مــن‪ .... -1/‬اجلنســية مبوجــب الســجل املدنــي رقــم‪ ... -2/ .......‬ســعودي‬\n‫اجلنســية مبوجــب بطاقــة تنقــل وعمــل للنازحــن مــن الــدول العربيــة‬\n‫املجــاورة برقــم ‪ .....‬حيــث إنــه باالطــاع علــى محاضــر البــاغ واالتصــال‬\n‫والقبــض والتفتيــش تبــن أنــه يف يــوم االثنــن املوافــق ‪1434/2/ 25‬ه ـ‬\n‫توفــرت معلومــات ملكافحــة املخــدرات مــن أحــد مصادرهــم الســرية عــن‬\n‫وجــود شــخص يدعــى ‪ .....‬مــن ســكان حــي ‪ ............‬ويســتخدم اجلــوال‬\n‫رقــم (‪ )....‬لــه نشــاط بالتوســط يف ترويــج احلشــيش ألحــد أعوانــه ويدعــى‬\n‫‪ ....‬وأفــاد املصــدر بأنــه علــى اســتعداد باإلطاحــة بــه باجلــرم املشــهود‬\n‫فتــم مراقبــة املــروج والوســيط ومت مشــاهدتهم يتقابلــون مــع أشــخاص‬\n‫مشــبوهني وقــام املصــدر باالتصــال علــى الوســيط ‪ .......‬وكانــت‬\n‫املكاملــة علــى مســمع مــن أفــراد الفرقــة القابضــة وطلــب منــه قطعــة‬\n‫حشــيش فأخبــره الوســيط بأنــه يف شــاطئ ‪ ............‬ودلــه علــى أحــد‬\n‫أعوانــه املتهــم ‪ .....‬وقــام بإرســال رقــم هاتفــه للمصــدر فتــم االتصــال‬\n‫عليــه علــى اجلــوال رقــم (‪ )....‬وأخبــره املصــدر بأنــه عــن طريــق ‪ ....‬فرحــب‬\n‫بــه وطلــب املصــدر منــه قطعــة حشــيش مببلــغ مائتــن ريــال فوافــق‬\n‫وحــدد مــكان االســتالم والتســليم خلــف مجمــع كائــن بحــي ‪............‬‬\n‫بالدمــام ومت تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا إبــراء للذمــة ومت ترقيــم‬\n‫املبلــغ احلكومــي وقــام أحــد االفــراد مبرافقــة املصــدر ومشــاهدة عمليــة‬\n‫الترويــج فتحركــوا حتــت أنظــار الفرقــة القابضــة وتوقفــوا باملــكان‬\n‫احملــدد فحضــر املتهــم ‪ ....‬مترجــا علــى قدميــه ونــزل املصــدر وتقابــا‬\n‫حتــت أنظــار الفرقــة القابضــة ومتــت عمليــة الترويــج حيــث قــام بتســليم‬\n\n\n                                                                                      ‫‪330‬‬\n\f      ‫املصــدر قطعــة ســمراء اللــون يشــتبه بــأن تكــون مــن احلشــيش املخــدر‬\n      ‫بلــغ وزنهــا (‪)6.8‬ســتة جــرام وثمانيــة مــن العشــرة مــن اجلــرام فتــم القبــض‬\n      ‫عليــه وبتفتيشــه عثــر معــه علــى اجلــوال الــذي مت التنســيق معــه مــن نــوع‬\n      ‫‪ .....‬يحمــل الرقــم املصنعــي ‪ ............‬وأقــر أمــام الفرقــة القابضــة بأن لدية‬\n      ‫باملنــزل قطعــة حشــيش داخــل منزلــه وباالنتقــال للمنــزل عثــر باملجلــس‬\n      ‫علــى املبلــغ احلكومــي وعلــى قطعــة ســمراء اللــون يشــتبه بــأن تكــون‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )35.2‬خمســة وثالثــن جرام ـ ًا واثنــان‬\n      ‫مــن العشــرة مــن اجلــرام وعثــر كذلــك علــى ســيجارة ملفوفــة يشــتبة بــأن‬\n      ‫تكــون ممزوجــة باحلشــيش املخــدر بلــغ وزنهــا(‪ )1,2‬واحــد جــرام واثنــن‬\n      ‫مــن العشــرة مــن اجلــرام كمــا مت القبــض علــى الوســيط املتهــم ‪....‬‬\n      ‫وبتفتيــش ســيارته مــن نــوع ‪ ......‬حتمــل اللوحــة رقــم (‪( )......‬مت تســليمها‬\n      ‫لصاحبهــا) عثــر بداخلهــا علــى علبــة نظــارات وجــد بداخلهــا عــدد خمــس‬\n      ‫قطــع ســمراء اللــون يشــتبه بــأن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫جميع ـ ًا (‪ )28,6‬ثمانيــة وعشــرون جــرام وســته مــن العشــرة مــن اجلــرام‬\n      ‫وعثــر علــى مســدس ربــع أســباني مــع مخزنــن فارغــة (مت بعثــة جلهــة‬\n      ‫االختصــاص لفحصــه واعــداد تقريــر بذلــك) وعثــر معــه كذلــك علــى‬\n      ‫هاتفــه الــذي اســتخدمه يف عمليــة الترويــج مــن نــوع ‪ .......‬يحمــل الرقــم‬\n      ‫املصنعــي (‪ )............‬وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪1074‬‬\n      ‫ك ش) لعــام ‪1434‬ه ـ إيجابيــة العينــات املرســلة مــن الكميــة املروجــة‬\n      ‫والكميــة املضبوطــة مــع املتهمــن ملــادة احلشــيش املخــدر وباســتجواب‬\n      ‫املتهــم األول ‪ ....‬أقــر بقيامــه بعمليــة الترويــج كمــا أقــر بحيازتــه للكمية‬\n      ‫املضبوطــة داخــل منزلــه البالــغ وزنهــا(‪ )35.2‬خمســة وثالثــن جرام ـ ًا‬\n      ‫واثنــان مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر وســيجارة ملفوفــة‬\n\n\n‫‪331‬‬\n\f‫ممزوجــة باحلشــيش املخــدر بلــغ وزنهــا (‪ )1,2‬واحــد جــرام واثنــن مــن‬\n‫العشــرة مــن اجلــرام بقصــد التعاطــي وأقــر بأنــه يتعاطــى احلشــيش املخــدر‬\n‫باســتجواب املتهــم الثانــي ‪ ...‬أقــر بقيامــه بالتوســط يف عمليــة الترويــج‬\n‫كمــا أقــر بحيازتــه للكميــة املضبوطــة داخــل الســيارة البالــغ عددهــا‬\n‫(‪ )5‬قطــع حشــيش بلــغ وزنهــا جميع ـ ًا (‪ )28,6‬ثمانيــة وعشــرين جرام ـ ًا‬\n‫وســته مــن العشــرة مــن اجلــرام بقصــد التعاطــي‪ ،‬وأقــر بأنــه يتعاطــى‬\n‫احلشــيش املخــدر وأنــه يقــوم بإعطــاء املتهــم األول احلشــيش املخــدر بــدون‬\n‫مقابــل وقــد انتهــى التحقيــق إلــى اتهــام كل مــن ‪ .... ...‬باالتــي‪-1 :‬بيــع‬\n‫املتهــم األول ‪ ...‬لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)6,8‬ســتة جــرام‬\n‫وثمانيــة مــن العشــرة مــن اجلــرام بقصــد االجتــار ‪-2‬توســط املتهــم الثانــي‬\n‫‪...‬يف بيــع قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا بلــغ وزنهــا (‪)6,8‬ســتة‬\n‫جــرام وثمانيــة مــن العشــرة مــن اجلــرام بقصــد االجتــار ‪-3‬حيــازة املتهــم‬\n‫األول لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )35.2‬خمســة وثالثــن‬\n‫جرام ـ ًا واثنــان مــن العشــرة مــن اجلــرام وســيجارة ملفوفــة ممزوجــة‬\n‫باحلشــيش املخــدر بلــغ وزنهــا (‪ )1,2‬واحــد جــرام واثنــن مــن العشــرة‬\n‫مــن اجلــرام بقصــد التعاطــي والترويــج ‪-4‬حيــازة املتهــم الثانــي عــدد‬\n‫خمــس قطــع مــن احلشــيش املخــدر بلــغ وزنهــا جميع ـ ًا (‪ )28,6‬ثمانيــة‬\n‫وعشــرون جــرام وســته مــن العشــرة مــن اجلــرام بقصــد التعاطــي والترويــج‬\n‫‪-5‬قيــام املتهــم الثانــي يف الســابق بإهــداء احلشــيش املخــدر للمتهــم‬\n‫األول ‪-6‬تعاطيهمــا للحشــيش املخــدر وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬إقرارهمــا مبــا اســند إليهمــا واملرفــق بــاألوراق لفــه رقــم (‪-17-16‬‬\n‫‪ -2)20-19-18‬مــا ورد مبحضــر والقبــض املرفــق بــاألوراق لفــه رقــم‬\n‫(‪ -3 )1‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه‬\n\n\n                                                                                    ‫‪332‬‬\n\f      ‫(‪ -4)22‬وجــود خمــس قطــع مقســمة بســيارة املتهــم الثانــي دليــل علــى‬\n      ‫أنهــا معــدة للترويــج وبالبحــث عــن ســوابقهما لــم يعثــر لهمــا علــى ســوابق‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة‬\n      ‫شــرع ٌا فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا أطلــب اآلتــي‪ -1:‬إثبــات‬\n      ‫مــا أســند إليهمــا وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واحلكــم عليهمــا بالعقوبــة الــواردة بالفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار‬\n      ‫إليــه وتطبيــق العقوبــة األشــد وفقــا للفقــرة(‪ )1‬مــن املــادة (‪)62‬مــن نظــام‬\n      ‫مكافحــة املخــدرات ‪ -2‬احلكــم مبنعهمــا مــن الســفر وفق ـ ٌا للفقــرة‬\n      ‫رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات ‪ -3‬احلكــم‬\n      ‫مبصــادرة الهاتــف اجلــوال العائــد للمتهــم األول مــن نــوع (‪ )......‬يحمــل‬\n      ‫الرقــم املصنعــي (‪ )............‬ورقــم االتصــال(‪ )....‬والهاتــف اجلــوال العائــد‬\n      ‫للمتهــم الثانــي مــن نــوع (‪ ).......‬يحمــل الرقــم املصنعــي (‪ )............‬ورقــم‬\n      ‫االتصــال(‪ )....‬الســتخدامهما يف الترويــج وفق ـ ٌا للفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة (‪ )53‬مــن ذات النظــام مــع احلكــم بإســقاط شــريحة الهاتفــن‬\n      ‫اجلــوال وعــدم صرفهــا لنفــس املتهمــن وفقـ ًا لتعميــم ســمو وزيــر الداخليــة‬\n      ‫رقــم (‪)9798‬وتاريــخ ‪1428/10/23‬ه ـ هكــذا ادعــى وبعــرض الدعــوى‬\n      ‫علــى املدعــى عليــه ‪ ...‬قــال مــا ذكــره املدعــي العــام مــن قيامــي ببيــع‬\n      ‫احلشــيش املخــدر بقصــد االجتــار وكذلــك قيامــي بحيــازة للحشــيش‬\n      ‫للترويــج والتعاطــي وكذلــك قيامــي بتعاطــي احلشــيش املخــدر فذلــك‬\n      ‫صحيــح كلــه وقــد اســتخدمت اجلــوال يف التنســيق للبيــع وأنــا تائــب مــن‬\n      ‫هــذا العمــل وال توجــد علــي ســوابق هكــذا أجــاب كمــا أجــاب املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام مــن قيامــي بالتوســط‬     ‫عليــه الثانــي ‪ ....‬قائ ـ ً‬\n\n\n‫‪333‬‬\n\f‫يف بيــع احلشــيش وحيــازة احلشــيش بقصــد التعاطــي وقيامــي يف الســابق‬\n‫بإهــداء احلشــيش لــ‪ ............‬وكذلــك قيامــي بتعاطــي احلشــيش فذلــك‬\n‫صحيــح كلــه وقــد اســتخدمت اجلــوال يف التنســيق للبيــع وأنــا تائــب مــن‬\n‫هــذا العمــل وال توجــد علــي ســوابق هكــذا أجــاب ثــم جــرى الرجــوع‬\n‫إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬دفتــر التحقيــق ص (‪)12-11‬‬\n‫محضــر واقعــة القبــض والضبــط والتفتيــش وهــو طبــق مــا ذكــر املدعــي‬\n‫العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )22‬تقريــر كيمــاوي‬\n‫شــرعي رقــم (‪1074‬ك ش ) املتضمــن ايجابيــة العينــات املرســلة ملــادة‬\n‫احلشــيش املخــدر كمــا وجــدت علــى لفــة رقــم (‪ )27-25‬كــرت بصمات‬\n‫ـاء علــى مــا تقــدم‬\n                   ‫املدعــى عليهمــا املتضمــن عــدم وجــود ســوابق لهمــا فبنـ ً‬\n‫مــن دعــوى املدعــي العــام وإجابــة املدعــى عليهمــا وإقرارهمــا بالدعــوى‬\n‫ـاء علــى الفقــرة (‪ )2‬مــن املادة‬\n                                 ‫وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا وبنـ ً‬\n‫رقــم (‪ )3‬والفقــرة (‪ )1‬مــن املــادة رقــم (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪)53‬‬\n‫والفقــرة (‪ )1‬مــن املــادة رقــم (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )60‬والفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫ونظــر ًا لعــدم وجــود ســوابق علــى املدعــى عليهمــا وملــا ظهــر منهمــا مــن‬\n‫إبدائهمــا للنــدم علــى فعلهمــا ومبــا أن احلشــيش مســكر حيــث ذكــر‬\n‫شــيخ اإلســام ابــن تيميــة يف مجمــوع الفتــاوى مــا نصــه‪( :‬والصحيــح أن‬\n‫احلشيشــة مســكرة كالشــراب وأن آكلهــا يحــد منهــا فهــي خمــر )‬\n                                                                     ‫(ج‪/29‬ص‪)135‬‬\n‫كمــا قــال‪( :‬وفيهــا مــن املفاســد مــا ليــس يف اخلمــر وإن كان يف اخلمــر‬\n‫مفســدة ليســت فيهــا وهــي احلــدة فهــي بالتحــرمي أولــى مــن اخلمــر ألن‬\n‫ضــرر آكل احلشيشــة علــى نفســه أشــد مــن ضــرر اخلمــر وضــرر شــارب‬\n\n\n                                                                                        ‫‪334‬‬\n\f      ‫اخلمــر علــى النــاس أشــد إال أنــه يف هــذه األزمــان لكثــرة أكل احلشيشــة‬\n      ‫صــار الضــرر الــذي منهــا علــى النــاس أعظــم مــن اخلمــر) مجمــوع الفتاوى‬\n      ‫(ج‪/29‬ص‪ )142‬لــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليهمــا كل‬\n      ‫مــن‪ ... ..... /‬باآلتــي‪-1 :‬بيــع ‪ ............‬لقطعــة مــن احلشــيش املخــدر بلــغ‬\n      ‫وزنهــا (‪)6,8‬ســتة جرامــات وثمانيــة مــن العشــرة مــن اجلــرام بقصــد‬\n      ‫االجتــار ‪-2‬توســط ‪ ...‬يف بيــع قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫بلــغ وزنهــا (‪)6,8‬ســتة جــرام وثمانيــة مــن العشــرة مــن اجلــرام بقصــد‬\n      ‫االجتــار ‪-3‬حيــازة ‪ ....‬لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)35.2‬‬\n      ‫خمســة وثالثــن جرامـ ًا واثنــان مــن العشــرة مــن اجلــرام وســيجارة ملفوفــة‬\n      ‫ممزوجــة باحلشــيش املخــدر بلــغ وزنهــا (‪ )1,2‬واحــد جــرام واثنــن مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد التعاطــي والترويــج ‪-4‬حيــازة املتهــم ‪ ....‬لعــدد‬\n      ‫خمــس قطــع مــن احلشــيش املخــدر بلــغ وزنهــا جميع ـ ًا (‪ )28,6‬ثمانيــة‬\n      ‫وعشــرين جرامـ ًا وســتة مــن العشــرة مــن اجلــرام بقصــد التعاطــي ‪-5‬قيــام‬\n      ‫‪ ............‬يف الســابق بإهداء احلشــيش املخدر ل‪-6 ...‬تعاطيهما للحشــيش‬\n      ‫املخــدر وقــررت معاقبتهمــا علــى ذلــك مبــا يلــي‪ :‬أوالً‪ :‬ســجن كل واحــد‬\n      ‫ـداء مــن تاريــخ إيقــاف‬‫مــن املدعــى عليهمــا ملــدة ســنتني وســتة أشــهر ابتـ ً‬\n      ‫كل واحــد منهمــا وجلــد كل واحــد منهمــا مائتــن وخمســن جلــدة‬\n      ‫تعزيــر ًا مفرقــة علــى دفعــات متســاوية بــن كل دفعــة وأخــرى مــدة‬\n      ‫التقــل عــن أســبوعني وتغــرمي كل واحــد منهمــا ألــف ريــال تدفــع للجهــة‬\n      ‫املختصــة وذلــك لقــاء بيــع احلشــيش والتوســط يف بيعــه وحيازتــه‪ .‬ثاني ـاً‪:‬‬\n      ‫منــع كل واحــد مــن املدعــى عليهمــا مــن الســفر ملــدة ســنتني وســتة‬\n      ‫أشــهر بعــد انتهــاء محكوميتهمــا املقــررة يف البنــد أوالً‪ .‬ثالثـاً‪ :‬مصــادرة‬\n      ‫اجلــواالت املوصــوف يف الدعــوى وإيداعهــا أو ثمنهــا لــدى اجلهــة املختصــة‬\n\n\n‫‪335‬‬\n\f‫وعــدم صــرف شــريحة اجلــوال لــكل واحــد منهمــا مــرة أخــرى‪ .‬رابع ـاً‪:‬‬\n‫جلــد كل واحــد مــن املدعــى عليهمــا ثمانــن جلــدة دفعــة واحــدة حــد‬\n‫املســكر ويكــون يف مــكان عــام بــن جمــع مــن النــاس‪ .‬وبــكل مــا‬\n‫تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليهمــا‬\n‫القناعــة باحلكــم وأمــا املدعــي العــام فقــرر االعتــراض واالكتفــاء‬\n‫بالئحــة الدعــوى العامــة وأمــرت برفــع املعاملــة إلــى محكمــة االســتئناف‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                  ‫حــرر يف ‪1434/04/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ‪1434/06/17‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة والنصــف وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االستئناف باملنطقة الشرقية برقم ‪ 34/1173702‬يف ‪1434/06/07‬هـ‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم ‪34223687‬‬\n‫يف ‪1434/05/27‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                            ‫‪1434/06/17‬هـ‬\n\n\n\n\n                                                                                   ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":327,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c851ea68fa4e311aecbc5219dec0e0024a73ce362b863130fff3bd3249f754e3","normalized_text_hash":"0c51c03d7f131151c7de37659d421df265a0e413040d4d2f5d6354a7c2d9ad1a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p327-34196192"},{"id":"e86abe0f-feed-593c-82ca-1417bcceeb1e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -حيازة حبوب محظورة بقصد التعاطي -إقرار -إدانة -تعزير بالسجن واجللد والغرامة واإلبعاد","document_number":"34215354","case_number":"34169514","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/9","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -حيازة حبوب محظورة بقصد التعاطي -إقرار -إدانة -تعزير بالسجن واجللد والغرامة واإلبعاد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34215354 :‬تاريخه ‪1434/05/9 :‬هـ‬\n                          ‫رقم الدعوى ‪34169514 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34250136‬تاريخه‪1434/06/24:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬حيــازة حبــوب محظــورة بقصــد‬\n       ‫التعاطــي ‪ -‬إقــرار ‪ -‬إدانــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واإلبعــاد‬\n                                                                          ‫عــن البــاد ‪.‬‬\n\n\n\n\n       ‫املــواد ( ‪ - 60‬الفقــرة الثانيــة مــن املــادة ‪ ) 56‬مــن نظام مكافحة املخدرات‬\n                                                              ‫واملؤثرات العقلية ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه ببيــع احلبــوب احملظــورة بقصــد‬\n       ‫االجتــار و الترويــج وحيــازة احلبــوب احملظــورة لقصــد الترويــج وتعاطيــه‬\n       ‫لهــا ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n       ‫الســجن واجللــد والغرامــة املاليــة وإبعــاده إلــى خــارج البــاد بعــد انتهــاء‬\n       ‫تنفيــذ العقوبــة وعــدم الســماح لــه بالعــودة مــرة أخــرى وعقوبتــه تعزيــر ًا‬\n       ‫لقــاء تســتره علــى مصــدر مــا باعــه ومــا ضبــط ‪ ،‬مت القبــض علــى املدعــى‬\n       ‫عليــه بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم بترويــج احلبــوب‬\n       ‫احملظــورة ومت التنســيق مــع أحــد املصــادر الســرية لإليقــاع بــه متلبس ـ ًا‬\n       ‫وتقابــل املصــدر مــع املدعــى عليــه يف املوقــع احملــدد ومت القبــض علــى‬\n       ‫املدعــى عليــه بعــد عمليــة االســتالم والتســليم إقــرار املدعــى عليــه‬\n\n‫‪337‬‬\n\f‫بالدعــوى وحكمــت احملكمــة بتعزيــره بالســجن واجللــد والغرامــة‬\n‫واإلبعــاد عــن البــاد ‪ ،‬قنــع املدعــى عليــه وقــرر املدعــي العــام االعتــراض‬\n            ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬       ‫بغيــر الئحــة ‪ُ -‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34169514‬وتاريــخ ‪ 1434/04/14‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34904477‬وتاريــخ ‪ 1434/04/14‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/05/14‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام وقــدم الئحــه دعــوى عامــه نصهــا كالتالــي ‪:‬‬\n‫فبصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام مبدينــة الريــاض ادعــي‬\n‫علــى ‪ ....../‬البالــغ مــن العمــر (‪ )23‬عامـ ًا ‪ ،‬مينــي اجلنســية مبوجــب رخصة‬\n‫اإلقامــة رقــم (‪ ).....................‬أعــزب ‪ -‬متعلــم ‪ -‬يقيــم مبدينــة الريــاض ‪-‬‬\n‫أوقف بتاريخ ‪1434/2/24‬هـ وأحيل إلى شــعبه ســجن امللز مبوجب أمر‬\n‫اإلحالــة ومتديــد التوقيــف رقــم (ه ـ ر‪ )21766/5/1‬وتاريخ ‪1434/3/1‬هـ‬\n‫اســتناد ًا إلــى القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي‬\n                             ‫علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n‫حيــث إنــه بتاريــخ ‪1434/2/24‬ه ـ توفــرت معلومــات لــدى إحــدى فــرق‬\n‫إدارة العمليــات التابعــة ملكافحــة املخــدرات مبنطقــة الريــاض مــن أحــد‬\n‫املصــادر الســرية عــن قيــام املذكــور بترويــج احلبــوب احملظــورة عليــه‬\n‫جــرى االنتقــال إلــى املوقــع حيــث شــوهد املذكــور واقــف علــى قدميــه‬\n‫يف أحــد الشــوارع املنزويــة فتــم تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا وتزويــده‬\n\n                                                                                         ‫‪338‬‬\n\f      ‫باملبلــغ احلكومــي املرقــم وقــدره (‪ )100‬مائــة ريــال ومت اإليعــاز للمصــدر‬\n      ‫بالترجــل مــن ســيارة الفرقــة وتوجــه للمذكــور واحتــك بــه علــى مــرأى‬\n      ‫مــن رقيــب الفرقــة وســلمه املصــدر املبلــغ احلكومــي املرقــم وســلم‬\n      ‫املذكــور للمصــدر (‪ )2‬حبتــن حتمــان عالمــة الكبتاجــون احملظــور‬\n      ‫عندهــا أعطيــت االشــارة الدالــة علــى إمتــام عمليــة الترويــج فتمــت‬\n      ‫مداهمــة املــروج والقبــض عليــه وبتفتيشــه شــخصي ًا عثــر بجيــب بنطالــه‬\n      ‫األيســر علــى كيــس نايلــون بداخلــه (‪ )78‬ثمــان وســبعون حبــة بنيــة‬\n      ‫اللــون حتمــل عالمــة الكبتاجــون احملظــور كمــا عثــر باجليــب نفســه‬\n      ‫علــى املبلــغ احلكومــي املرقــم (متــت مطابقتــه) ومبناقشــته عــن واقعــة‬\n      ‫الترويــج أقــر بكامــل تفاصيلهــا علــى مســمع مــن الفرقــة القابضــة‬\n      ‫(مت رد اجلــوال املضبــوط معــه مــن نــوع ‪ ......‬مبوجــب اخلطــاب رقــم (ه ـ‬\n      ‫ا للمصــادرة‬ ‫ر‪ )29749/5/1‬وتاريــخ ‪1434/2/22‬ه ـ لكونــه ليــس محـ ً‬\n      ‫اســتناد ًا للمــادة (‪ )86‬مــن نظــام اإلجــراءات اجلزائيــة) ‪.‬وقــد أثبــت التقرير‬\n      ‫الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n      ‫الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪/2268‬س) لعــام ‪1434‬ه ـ‬\n      ‫احتــواء احلبتــن املبيعــة وعينــة احلبــوب املضبوطــة ملــادة اإلمفيتامــن وهــو‬\n      ‫مــن املــواد املنبهــه واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n                                       ‫مكافحــه املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وبســماع أقوالــه األوليــة واســتجوابه أقــر ببيــع (‪ )2‬حبتــان مــن حبــوب‬\n      ‫اإلمفيتامــن املنبــه احملظــور وحيازتــه (‪ )78‬ثمــان وســبعون حبــه مــن‬\n      ‫حبــوب الكبتاجــون بقصــد االجتــار والترويــج وتعاطيــه إياهــا ودون لــه‬\n                                                                       ‫إقــرار بذلــك ‪.‬‬\n      ‫وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام لــ‪ /‬ببيــع (‪)2‬‬\n\n\n‫‪339‬‬\n\f‫حبتــان مــن حبــوب اإلمفيتامــن املنبــه احملظــور بقصــد االجتــار والترويــج‬\n‫وحيازتــه (‪ )78‬ثمــان وســبعون مــن حبــوب اإلمفيتامــن املنبــه احملظــور‬\n‫بقصــد الترويــج وتعاطيــه إياهــا املجــرم مبوجــب املــادة (الثالثــة) مــن نظام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وتســتره علــى مصــدر مــا باعــه ومــا‬\n                                              ‫ضبــط املعاقــب علــى ذلــك شــرع ًا ‪.‬‬\n                                                   ‫وذلك لألدلة والقرائن التالية ‪-:‬‬\n‫‪ -1‬مــا تضمنــه اعترافــه حتقيقـ ًا املنــوه عنــه املــدون علــى الصفحتــن رقــم‬\n                           ‫(‪ )2-1‬مــن دفتــر التحقيــق املرفــق لفــه رقــم (‪. ) 13‬‬\n‫‪ -2‬مــا تضمنــه إقــرار املذكــور املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                             ‫(‪ )3‬مــن دفتــر التحقيــق املرفــق لفــه رقــم ( ‪. ) 13‬‬\n‫‪ -3‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املرفق‬\n                                                          ‫علــى اللفتــن رقــم (‪. )4-3‬‬\n‫‪ -4‬مــا تضمنــه محضــر القبــض ومحضــر مطابقــة املبلــغ املرقــم املنــوه‬\n‫عنهمــا واملدونــان علــى الصفحتــن رقــم (‪ )2-1‬مــن ملــف إجــراءات‬\n                                              ‫االســتدالل املرفــق لفــه رقــم (‪. )1‬‬\n‫‪ -5‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق علــى‬\n                                                                ‫اللفــة رقــم ( ‪. ) 20‬‬\n‫وببحــث ســوابقه اتضــح عــدم وجــود ســوابق مســجلة عليــه حتــى تاريخــه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظام ـ ًا ‪ ،‬لــذا اطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                            ‫باآلتــي‪-:‬‬\n‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة (األولــى)‬\n\n\n                                                                                         ‫‪340‬‬\n\f      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n      ‫إليــه وتشــديد العقوبــة عليــه وفق ـ ًا للفقــرة (ج) مــن بنــد (ثاني ـاً) مــن ذات‬\n      ‫املــادة املشــار إليهــا ‪ ،‬وإعمــال الفقــرة (األولــى) مــن املــادة (‪ )62‬مــن ذات‬\n                                                                           ‫النظــام بحقــه ‪.‬‬\n      ‫‪ -2‬إبعــاده إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه وعــدم الســماح‬\n                                                  ‫لــه بالعــودة إليهــا مــرة أخــرى وفقـ ًا‬\n                          ‫للفقرة (الثانية) من املادة (‪ )56‬من النظام املشار إليه ‪.‬‬\n      ‫‪ -3‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا باعــه ومــا ضبــط‬\n                                                                       ‫‪ .‬هــذه دعــواي ‪.‬‬\n      ‫وبســؤال املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام مــن‬\n      ‫اتهامــي ببيــع حبتــن محظــوره صحيــح ووجــد بحوزتــي ثمــان وســبعني‬\n      ‫حبــة مــن نفــس النــوع حتمــل عالمــه الكبتاجــون عائــدة لــي بقصــد‬\n      ‫الترويــج وقــد تعاطيــت هــذا النــوع مــن احلبــوب ونــادم علــى مــا حصــل‬\n      ‫منــي وتائــب وليــس علــي ســوابق واشــتريت هــذه احلبــوب مــن شــخص‬\n      ‫يف ‪ ............‬يقــول ان هكــذا اجــاب ‪ .‬وباالطــاع علــى املعاملــه وجــدت‬\n      ‫باللفــه (‪ )20‬تقريــر كيميائــي برقــم ‪/44/2/2268‬ك يف ‪1434/3/8‬هـ‬\n      ‫مضمونــه املرســل (أ) عبــاره عــن حبتــن حتمــل عالمــه الكبتاجــون ثبــت‬\n      ‫احتــواء كل حبــه منهــا ملــاده االمفيتامــن واملرســل (ب) عبــاره عــن ســت‬\n      ‫حبــات ثبــت احتــواء كل حبــه ملــاده االمفيتامــن ووجــدت باللفــه (‪)14‬‬\n      ‫بيــان مــن االدلــه اجلنائيــه تضمــن عــدم وجــود ســوابق بحقــه وباالطــاع‬\n      ‫علــى رخصــه اقامتــه وجــدت تاريــخ ميــاده ‪1411/4/7‬ه ـ ‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واالجابــه وحيــث صــادق املدعــى عليــه املدعــي‬\n      ‫العــام يف دعــواه ولعــدم وجــود ســوابق بحقــه ولصغــر ســنه حســب رخصــة‬\n\n\n‫‪341‬‬\n\f‫اقامتــه ولقلــه احلبــوب التــي قــام ببيعهــا وملــا قــرره مــن النــدم والتوبــه‬\n‫وبنــاء علــى املــاده (‪ )60‬مــن نظــام مكافحــه املخــدرات لــذا قــررت‬\n‫النــزول عــن احلــد االدنــى املنصــوص عليــه يف املــاده (‪)38‬واملــاده (‪ )62‬مــن‬\n‫ذات النظــام وحكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬ثبــت لــدي ادانتــه‬\n‫ببيــع حبتــن مــن حبــوب االمفيتامــن احملظــور بقصــد االجتــار والترويــج‬\n‫وحيازتــه ثمــان وســبعني حبــه مــن حبــوب االمفيتامــن احملظــور بقصــد‬\n‫الترويــج ويعــزر لذلــك بســجنه ســنه اعتبــارا مــن تاريــخ توقيفــه وجلــده‬\n‫مائــه وخمســن جلــده مفرقــه علــى ثــاث دفعــات مســتاويه وتغرميــه‬\n‫الــف ريــال تدفــع للخزينــه العامــه للدولــه وابعــاده الــى خــارج اململكــه‬\n‫بعــد انتهــاء تنفيــذ عقوبــه ســجنه وفقــا للفقــره الثانيــه مــن املــاده(‪)56‬‬\n‫مــن ذات النظــام وثبــت لــدي ادانتــه بتعاطــي احلبــوب احملظــوره مــن ذات‬\n‫النــوع ويعــزر لذلــك بجلــده ســبعني جلــده دفعــه واحــده تنفــذ اوال وبعــد‬\n‫عشــره ايــام ينفــذ بحقــه الدفعــه االولــى مــن جلــد التعزيــر اعــاه كمــا‬\n‫ثبــت لــدي ادانتــه بتســتره علــى مصــدر مــا باعــه ومــا ضبــط بحوزتــه‬\n‫وتعزيــره علــى ذلــك داخــل يف التعزيــر اعــاه وبتــاوة احلكــم قنــع بــه‬\n‫املدعــى عليــه وقــرر املدعــي العــام اعتراضــه بــدون الئحــه وعليــه حصــل‬\n‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                           ‫يف ‪ 1434/05/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ 34904477‬وتاريــخ ‪/29‬‬\n‫‪ 1434/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمة‬\n‫الشــيخ‪ ............/‬املســجل برقــم ‪ 34215354‬وتاريــخ ‪1434/5 /19‬ه ـ‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪ ( ............/‬مينــي اجلنســية ) يف قضيــة‬\n      ‫مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل بــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قــررت الدائــرة املصادقــة علــى احلكــم ‪ .‬و اهلل املوفــق وصلــى اهلل علــى‬\n                                                 ‫نبينــا محمــد وآلــه وصحبــه وســلم‪0‬‬\n\n\n\n\n‫‪343‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":337,"source_page_end":343,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c4592bf447188b46612a5e5233191f189fec013f7f14eb044ac4d8c1d3e8ed14","normalized_text_hash":"2dd3a102a9405affbb03c9b60bfbe8a94fcebc0d6076ac07283d9714057ab4e8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p337-34215354"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0a876673-a697-5786-ae72-76411a450615","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -قات -نقل بقصد االجتار -هروب املدعى عليه من رجال األمن -إقرار -التعزير بالسجن واجللد والغرامة.","document_number":"3460741","case_number":"34111631","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/11","year":"1434","subject":"مخدرات -قات -نقل بقصد االجتار -هروب املدعى عليه من رجال األمن -إقرار -التعزير بالسجن واجللد والغرامة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3460741:‬تاريخه‪1434/3/11:‬هـ‬\n                   ‫رقم الدعوى‪34111631:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34193498‬تاريخه‪1434/4/21 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬قــات ‪ -‬نقــل بقصــد االجتــار ‪ -‬هــروب املدعــى عليــه مــن رجال‬\n                  ‫األمــن ‪ -‬إقــرار ‪ -‬التعزيــر بالســجن واجللــد والغرامة‪.‬‬\n\n\n\n\n                     ‫‪ -1‬قرار مجلس الوزراء رقم‪ 11‬يف ‪1374/2/1‬هـ‬\n                    ‫‪ -2‬األمر السامي رقم ‪ 59633‬يف ‪1432/12/9‬هـ‪.‬‬\n    ‫‪ -3‬املادة الثالثة من قرار وزير الداخلية رقم ‪2057‬يف ‪1404/5/26‬هـ‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد االجتــار‬\n‫والهــروب مــن رجــال األمــن وطلــب إثبــات مــا أســند إليــه واحلكــم بتعزيره‬\n‫ومنعــه مــن الســفر وتعزيــره لقــاء هروبــه مــن رجــال األمــن ‪ ،‬وأثنــاء قيــام‬\n‫دوريــة املجاهديــن بحراســة احلــدود أقبلــت عليهــا ســيارة يقودهــا املدعــى‬\n‫عليــه فطلــب منــه التوقــف ولــم ميتثــل فتمــت مطاردتــه والقبــض عليــه‬\n‫وبتفتيــش الســيارة عثــر بهــا علــى كمية مــن نبات القات‪،‬وأثبــت التقرير‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور‬\n‫‪،‬وصــادق املدعــى عليــه باالدعــاء املوجــه إليــه بنقــل القــات حلســاب الغيــر‬\n‫مقابــل مبلــغ مالــي لقصــد الترويــج حكمــت احملكمــة احلكــم بتعزيــره‬\n\n\n                                                                                      ‫‪302‬‬\n\f      ‫بالســجن خمــس ســنوات وجلــده خمســمائة جلــدة مفرقــة علــى دفعــات‬\n      ‫كل دفعــة خمســون و غرامــة ماليــة قدرهــا خمســة عشــر ألــف ريــال‬\n      ‫تــودع يف بيــت مــال املســلمني و صــرف النظــر عــن مطالبــة املدعــي العــام‬\n      ‫مبنعــه مــن الســفر خــارج البــاد لعــدم اشــتمال املــادة املعاقــب بهــا املدعــى‬\n      ‫عليــه ‪ ،‬قنــع املدعــى عليــه باحلكــم واعتــرض املدعــي العــام مكتفي ـ ًا‬\n                   ‫بالئحــة الدعــوى و صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34111631‬وتاريــخ ‪1434/03/08‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34586907‬وتاريــخ ‪1434/03/08‬ه ـ ففــي يــوم‬\n      ‫االثنني املوافق‪1434/03/09‬هـ افتتحت اجللســة الســاعة ‪ 09 : 15‬وفيها‬\n      ‫حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم(‪ ).....‬وتاريــخ ‪1433/3/22‬ه ـ‬\n      ‫واملدعــى عليــه ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪).....‬‬\n      ‫وقــدم املدعــي العــام دعــوى محــررة تتضمــن أنــه ‪ :‬بتاريــخ ‪1434/2/11‬هـ‬\n      ‫وأثنــاء قيــام إحــدى دوريــات املجاهدين بحراســة احلــدود واملواقع احملددة‬\n      ‫لهــا وأثنــاء جتولهــم يف مركــز ‪.....‬وحتديــدا علــى اخلــط املــؤدي مــن ‪.....‬‬\n      ‫للمثلــث املــؤدي مــن ‪ ......‬لصبيــا وبقريــة ‪.....‬أقبلــت عليهــم ســيارة مــن‬\n      ‫نــوع ‪....‬حتمــل اللوحــة رقــم (‪ ).....‬تعــود ملكيتــه للمدعــو ‪(..... /‬أعيــدت‬\n      ‫ملالكهــا) متجــه مــن جهــة ‪.....‬باجتــاه مثلــث ‪.....‬ومت التأشــير لــه بالوقــوف‬\n      ‫ولــم ميتثــل لذلــك وقــام بالرجــوع إلــى اخللــف ومت ابــاغ القيــادة ومت إبــاغ‬\n\n‫‪303‬‬\n\f‫العمليــات ومتــت مطاردتــه وقــد اجتــه يســار اخلــط ‪.....‬باجتــاه قريــة ‪.....‬ومت‬\n‫إطــاق طلقتــن حتذيريــة لغــرض إيقافــه وكانــت هنــاك ســيارة أخــرى‬\n‫مــن نــوع ‪ ....‬تضايــق الدوريــة ولــم تتمكــن الدوريــة مــن أخــذ لوحتهــا‬\n‫ومت القبــض علــى املدعــى عليــه وكانــت الســيارة بقيادتــه وبتفتيــش‬\n‫الســيارة عثــر بهــا علــى كميــة مــن نبــات القــات بلــغ وزنــه (‪133‬كجــم)‬\n‫مائــة وثالثــة وثالثــن كيلــو جرامـ ًا أثبــت التقريــر الكيميائــي الشــرعي‬\n‫رقــم (‪.....‬بتاريــخ ‪1434/2/19‬ه ـ إيجابيــة العينــة املرســلة مــن الكميــة‬\n‫املضبوطــة لنبــات القــات احملظــور وباســتجواب املدعــى عليــه أقــر بنقلــه‬\n‫كميــة القــات املضبوطــة البالــغ وزنهــا (‪133‬كجــم) مائــة وثالثــة‬\n‫وثالثــن كيلــو جرامـ ًا مــن نبــات القــات احملظــور حيث ذكــر بأن هناك‬\n‫شــخصا ســيقابله بجــوار محطــة ‪.....‬ويقــوم مبتابعتــه إلــى مــكان إنــزال‬\n‫الكميــة مقابــل مبلــغ مالــي وقــدره (‪10‬ريــاالت) لــكل حبــة وقــد أســفر‬\n‫التحقيــق معــه عــن توجيــه االتهــام إليــه بنقــل مــا وزنــه (‪133‬كجــم) مائــة‬\n‫وثالثــة وثالثــن كيلــو جرامـ ًا مــن نبــات القــات احملظــور بقصــد االجتــار‬\n‫وهروبــه مــن رجــال األمــن وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء‬\n‫يف أقوالــه مبحضــر االســتجواب املرفــق ‪ -2‬مــا جــاء مبحضــر القبــض‬\n                                          ‫والتفتيــش املشــار لــه املرفــق بــاألوراق‬\n‫‪ -3‬مــا جــاء بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق ‪ -4‬مــا‬\n‫جــاء مبحضــر القبــض هروبــه مــن رجــال األمــن وحيــث إن مــا أقــدم عليــه‬\n‫املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب قــرار مجلس‬\n‫الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا أطلب ما‬\n‫يلــي‪ -1 :‬إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره يف ضــوء املــادة‬\n‫(الثالثــة) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذا لألمــر الســامي‬\n\n\n                                                                                         ‫‪304‬‬\n\f      ‫الكــرمي رقــم (‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ ‪ -2‬منعــه مــن الســفر‬\n      ‫بعــد انتهــاء محكوميتــه اســتنادا لتعميــم وزيــر الداخليــة رقــم (‪)69935‬‬\n      ‫وتاريــخ ‪1433/6/18‬ه ـ ‪ -3‬تعزيــره شــرعا لقــاء هروبــه مــن رجــال األمــن‬\n      ‫وبســؤال املدعــى عليــه املذكــور أعــاه أجــاب باالعتــراف بنقــل مــا وزنــه‬\n      ‫مائــة وثالثــة وثالثــون كيلــو جرام ـ ًا مــن نبــات القــات احملظــور حلســاب‬\n      ‫الغيــر مقابــل مبلــغ مالــي هكــذا أجــاب املدعــى عليــه عنــد ذلــك جــرى‬\n      ‫منــا االطــاع علــى التقريــر الكيميائــي الشــرعي وعلــى محضــري الوزن‬\n      ‫والقبــض فوجــدت متطابقــة ملــا جــاء بالدعــوى وبنــاء علــى مــا ذكــر مــن‬\n      ‫دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليــه ‪.....‬ســعودي اجلنســية‬\n      ‫باالعتــراف بنقــل مــا وزنــه مائــة وثالثــة وثالثــون كيلــو جرام ـ ًا حلســاب‬\n      ‫الغيــر مقابــل مبلــغ مالــي لــذا فقــد ثبــت لــدى شــرع ًا إدانــة املدعــى عليــه‬\n      ‫املذكــور بنقــل كميــة نبــات القــات احملظــور املوضحــة أعــاه حلســاب‬\n      ‫الغيــر مقابــل مبلــغ مالــي لقصــد الترويــج وهــو يســتحق العقوبــة علــى‬\n      ‫ذلــك وفــق املــادة الثالثــة مــن قــرار ســمو وزيــر الداخليــة رقــم ‪2057‬‬\n      ‫وتاريــخ ‪1404/5/26‬ه ـ اســتنادا لقــرار مجلــس الــوزراء رقــم ‪ 11‬وتاريــخ‬\n      ‫‪1374/2/1‬ه ـ إنفــاذ ًا لألمــر الســامي الكــرمي رقــم ‪ 59633‬وتاريــخ‬\n      ‫‪1432/12/9‬ه ـ وملــا ذكــر أعــاه فقــد حكمــت بتعزيــره بالســجن ملــدة‬\n      ‫خمــس ســنوات مــن تاريــخ إيقافــه يف ‪1434/2/11‬ه ـ وجلــده بخمســمائة‬\n      ‫جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون جلــدة بــن الدفعــة واألخــرى‬\n      ‫عشــرة أيــام وغرامــه ماليــة قدرهــا خمســة عشــر ألــف ريــال تــودع بيــت‬\n      ‫مــال املســلمني وصرفــت النظــر عــن مطالبــة املدعــي العــام مبنــع املدعــى‬\n      ‫عليــه مــن الســفر خــارج البــاد لعــدم اشــتمال املــادة املعاقــب بهــا املدعــى‬\n      ‫عليــه لذلــك واكتفــاء بالعقوبــة الصــادرة بحــق املدعــى عليــه أعــاه هــذا‬\n\n\n‫‪305‬‬\n\f‫مــا حكمــت بــه وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫وطلــب املدعــي العــام اســتئناف احلكــم مكتفيـ ًا بالئحــة االدعــاء العــام‬\n‫وأمــرت بتنظيــم القــرار الــازم مبوجبــه ورفعــه حملكمــة االســتئناف‬\n‫مبنطقــة عســير لدراســته وإبــداء مــا تــراه نحــوه وصلــى اهلل وســلم علــى‬\n                 ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/3/9‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائية بجازان برقــم ‪34586907‬‬\n‫وتاريــخ ‪1434/3/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضي‬\n‫باحملكمــة الشــيخ ‪..... /‬برقــم ‪ 3460741‬وتاريــخ ‪1434/3/11‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضــد ‪ ...../‬يف قضيــة (قــات) علــى الصفــة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪306‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":302,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c070a1dca5269b2b4474468ea4685375172cb5aafd79b9605d703ba07edf5a97","normalized_text_hash":"7a898e95d01df899f2d22d388b810c90106d946161597fd2f49207fc31723c66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p302-3460741"},{"id":"21f3d179-5859-5a5d-837d-29d03df2f929","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة بقصد اإلجتار -تعاطي احلشيش املخدر -اإلقرار -مصادرة السيارة -إقامة حد املسكر على متعاطي احلشيش -تعزير املدعي عليه بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ احلكومي.","document_number":"34171068","case_number":"34126420","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/24","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة بقصد اإلجتار -تعاطي احلشيش املخدر -اإلقرار -مصادرة السيارة -إقامة حد املسكر على متعاطي احلشيش -تعزير املدعي عليه بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإعادة املبلغ احلكومي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34171068:‬تاريخه ‪1434/03/24:‬هـ‬\n                        ‫رقم الدعوى ‪34126420:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34212596‬تاريخه‪1434/05/13:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة بقصــد اإلجتــار ‪ -‬تعاطــي‬\n      ‫احلشــيش املخــدر ‪ -‬اإلقــرار‪ -‬مصــادرة الســيارة ‪ -‬إقامــة حــد املســكر علــى‬\n      ‫متعاطــي احلشــيش ‪ -‬تعزيــر املدعــي عليــه بالســجن واجللــد والغرامــة‬\n                         ‫واملنــع مــن الســفر واملصــادرة وإعــادة املبلــغ احلكومــي‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى ‪( :‬يأيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واالنصــاب‬\n           ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون)‪.‬‬\n                    ‫‪ -2‬قوله تعالى ‪( :‬والتفسدو ا يف االرض بعد اصالحها)‪.‬‬\n      ‫‪ -3‬املــواد (‪ )2/3‬و (‪ )1/38‬و (‪ )1/56‬و (‪ )1/53‬مــن نظــام مكافحــة‬\n                                                  ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج عــدد مــن حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة وتعاطــي احلشــيش‪ ،‬وطلــب املدعــي‬\n      ‫العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واجللــد والغرامــة واملنــع مــن الســفر وإقامــة حــد املســكر عليــه لتعاطيــه‬\n      ‫احلشــيش املخــدر‪ ،‬حيــث وردت معلومــات ملكافحــة املخــدرات مــن أحــد‬\n      ‫مصادرهــا عــن قيــام املدعــى عليــه بترويــج احلشــيش املخــدر واحلبــوب‬\n\n‫‪307‬‬\n\f‫احملظــورة ومت متكــن املصــدر مــن االتصــال علــى املدعــى عليــه علــى‬\n‫مســمع مــن أفــراد الفرقــة القابضــة و مت االتفــاق علــى شــراء عــدد مــن‬\n‫احلبــوب احملظــورة‪ ،‬مت تفتيــش املصــدر وتزويــده باملبلــغ احلكومــي‬\n‫املرقــم و تكليــف أحــد أفــراد الفرقــة مبرافقتــه ويف املــكان احملــدد‬\n‫حضــر املدعــي عليــه بســيارته ومتــت عمليــة االســتالم والتســليم‪ ،‬غــادر‬\n‫املدعــى عليــه املوقــع مســرع ًا و اختفــى عــن األنظــار ومت التعميــم عليــه‬\n‫وبعــد شــهرين ونصــف تقريبـ ًا مت القبــض عليــه مــن قبــل جــوازات جســر‬\n‫امللــك فهــد‪ ،‬كمــا أقــر املدعــي عليــه مبــا نســب إليــه‪ ،‬بنــاء علــى مــا تقدم‬\n‫صــدر احلكــم بإثبــات إدانــة املدعــى عليــه مبــا نســب إليــه و احلكــم‬\n‫عليــه بإقامــة حــد املســكر وتعزيــره بالســجن واجللــد والغرامــة واملنــع مــن‬\n‫الســفر ومصــادرة الســيارة و الهاتــف اجلــوال وإعــادة املبلــغ احلكومــي‬\n                                 ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n‫برقــم وتاريــخ ‪1434/3/16‬ه ـ املقيــدة باحملكمــة برقــم وتاريــخ‬\n‫‪1434/3/16‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ ..... /‬ضد ‪ ، .... /‬حامل‬\n‫الســجل املدنــي رقــم (‪ ).....‬ففــي يــوم الثالثــاء ‪1434/ 3 / 24‬ه ـ فتحــت‬\n‫اجللســة الســاعة ‪ 11 : 15‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا‬\n‫يلــي ‪( :‬بصفتــي مدعيـ ًا عامــا يف دائــرة التحقيــق واالدعاء العام مبحافظة‬\n‫القطيــف أدعــي علــى ‪ ، .... :‬البالــغ مــن العمــر (‪ ،)26‬ســعودي اجلنســية‬\n\n                                                                                        ‫‪308‬‬\n\f      ‫مبوجــب الســجل املدنــي رقــم (‪ ،).....‬غيــر محصــن ‪ ،‬موظــف أهلــي ‪،‬‬\n      ‫قبــض عليــه بتاريــخ ‪1409/8/14‬ه ـ ‪ ،‬وأحيــل إلــى ســجن محافظــة‬\n      ‫القطيــف اســتنادا للقــرار الــوزاري رقــم (……) بتاريــخ ‪1428/7/9‬هــ‪.‬‬\n      ‫حيــث أنــه بتاريــخ ‪1433/11/8‬ه ـ وردت معلومــات لرجــال مكافحــة‬\n      ‫املخــدرات بالدمــام مــن أحــد مصادرهــم الســرية عــن قيــام املدعــى عليــه‬\n      ‫بترويــج احلشــيش املخــدر واحلبــوب احملظــورة‪ ،‬فتــم متكينــه مــن االتصال‬\n      ‫علــى جــوال املدعــى عليــه رقــم (‪ ).....‬ورقمــه املصنعــي (‪ ،).....‬وطلــب منــه‬\n      ‫خمســا وعشــرين حبــة مــن احلبــوب احملظــورة‪ ،‬فأجابــه باملوافقــة‬  ‫ً‬      ‫(‪)25‬‬\n      ‫وأن قيمتهــا (‪ )600‬ســت مائــة ريــال وحــدد مــكان التســليم علــى طريــق‬\n      ‫صفــوى ‪ -‬وكانــت املكاملــة علــى مســمع مــن أفــراد الفرقــة القابضــة‪،‬‬\n      ‫فجــرى تفتيــش املصــدر وتكليــف أحــد أفــراد الفرقــة القابضــة‬\n      ‫مبرافقتــه وتزويــد املرافــق باملبلــغ املرقــم وقــدره (‪ )600‬ســت مئــة ريــال‪،‬‬\n      ‫وبانتقالهــم للموقــع املتفــق عليــه حضــر املدعــى عليــه علــى ســيارة نــوع‬\n      ‫‪ .....‬لوحــة رقــم (‪ ).....‬وقــام باســتالم املبلــغ وغــادر املوقــع‪ ،‬وبعــد ربــع‬\n      ‫ســاعة عــاد وتوقــف بجانــب املصــدر ومرافقــه وســلم املصــدر (‪ )21‬واحــد‬\n      ‫وعشــرين حبــة اثبــت التقريــر الكيمــاوي الشــرعي رقــم (……‪ ).‬وتاريخ‬\n      ‫‪1433/11/8‬ه ـ ايجابيــة عينتهــا ملــادة االمفيتامــن املنبهــة احملظــورة ‪،‬‬\n      ‫وغــادر املوقــع مســرعا واختفــى عــن األنظــار فتــم التعميــم عليــه‪ .‬وبتاريــخ‬\n      ‫‪ 1434/1/22‬ه ـ قبــض علــى املدعــى عليــه مــن قبــل جــوازات جســر امللك‬\n      ‫فهــد‪ ،‬وبتاريــخ ‪1434/1/24‬ه ـ أودع التوقيــف مبكافحــة املخــدرات ‪،‬‬\n      ‫و جــرى التعــرف عليــه مــن قبــل أفــراد الفرقــة القابضــة واعــد محضــر ًا‬\n      ‫بذلــك‪ .‬وباســتجوابه أفــاد بــأن رقــم الهاتــف احملمــول (‪ ).....‬عائــد لــه‬\n      ‫يف الســابق وان ســيارته نــوع ‪ .....‬موديــل ‪ 93‬لوحــة رقــم (‪ ، ).....‬واقــر‬\n\n\n‫‪309‬‬\n\f‫بتعاطــي احلشــيش املخــدر منــذ ســنة وآخــر مــرة كانــت قبــل القبــض‬\n‫عليــه بيــوم ‪ .‬وقــد أســفر التحقيــق عــن اتهامــه ببيــع عــدد (‪ )21‬واحــد‬\n‫وعشــرين حبــة مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد االجتــار‬\n‫و تعاطــي احلشــيش املخــدر ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪-1 :‬مــا ورد‬\n‫باســتجوابه املنــوه عنــه املرفــق علــى اللفــات رقــم (‪-2 .)19-17‬محاضــر‬\n‫البــاغ و االتصــال و التعــرف و االنتقــال و الضبــط املنــوه عنهــا املدونــة‬\n‫علــى الصفحــات رقــم (‪ )13-12 ، 4 ، 2‬مــن ملــف التحقيــق‪-3 .‬التقريــر‬\n‫الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم(‪ . )7‬وبالبحــث‬\n‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق مســجله‪ .‬وحيــث إن‬\n‫مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ ،‬فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب إثبــات مــا اســند إليــه‬\n‫وفــق الفقــرة رقــم(‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪.1 :‬بعقوبــة الســجن واجللــد‬\n‫والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم(‪ )38‬مــن النظــام‬\n‫‪،‬وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )62‬من ذات النظام ‪ ،‬والتشــديد‬\n‫عليــه كــون املــادة املروجــة حبــوب منبهــة وفــق الفقــرة (‪/2‬ج) مــن املــادة‬\n‫رقــم(‪ )38‬مــن النظــام‪ ،‬و اســتنادا لبرقيــة صاحــب الســمو امللكــي وزيــر‬\n‫الداخليــة رقــم(……………‪ ).‬وتاريــخ ‪1427/2/8‬ه ـ ‪.2 .‬منعــه مــن‬\n‫الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام املشــار‬\n‫اليــه‪.3 .‬مصــادرة جوالــه و ســيارته املوصوفــن بالوقائــع وفــق الفقــرة رقــم‬\n‫(‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬وعــدم صــرف شــريحة اجلــوال‬\n‫لنفــس املدعــى عليــه وفقـ ًا لتعميــم وزيــر الداخليــة رقــم (……………‪).‬‬\n‫وتاريــخ ‪1428/2/10-9‬ه ـ ‪-4 .‬إلزامــه بدفــع املبلــغ املرقــم الــذي لــم يتــم‬\n\n\n                                                                                     ‫‪310‬‬\n\f              ‫العثــور عليــه وفــق تعميــم وزيــر الداخليــة رقــم (‪)65980/4/5/1‬‬\n      ‫وتاريــخ ‪1428/10/23-22‬هــ‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى‬\n      ‫علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف الدعــوى كلــه صحيــح‬\n      ‫والســيارة املذكــورة يف الدعــوى عائــدة لــي وأنــا تائــب ونــادم وأطلــب مــن‬\n      ‫اهلل العفــو والصفــح هــذا جوابــي وبتصفــح املعاملــة وجــدت علــى اللفــة‬\n      ‫رقــم ‪ 7‬التقريــر الكيمــاوي رقــم ‪ 4052‬ك ش املتضمــن ‪ ( :‬إيجابيــة‬\n      ‫العينــة ملــادة االمفيتامــن ) ا‪.‬ه ـ فبنــاء علــى مــا تقدم من الدعــوى واإلجابة‬\n      ‫وحيــث أقــر املدعــى عليــه مبــا نســب إليــه ولقولــه تعالــى ‪ ( :‬يــا أيهــا الذيــن‬\n      ‫آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان‬\n      ‫فاجتنبــوه لعلكــم تفلحــون ) وقولــه ( وال تفســدوا يف األرض بعــد‬\n      ‫إصالحهــا ) وبنــاء علــى املــواد ‪ 2/3‬و ‪ 1/38‬و ‪ 1/56‬و ‪ 1/53‬مــن نظــام‬\n      ‫مكافحــة املخــدرات ولكــون املدعــى عليــه ليــس مــن أربــاب الســوابق‬\n      ‫وإلقــراره بذنبــه ومــا أبــداه مــن توبــة ممــا يخولــه االســتفادة مــن املــادة ‪60‬‬\n      ‫مــن النظــام فقــد حكمــت مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه ببيــع‬\n      ‫واحــد وعشــرين حبــة مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد‬\n      ‫االجتــار و تعاطــي احلشــيش املخــدر ‪-2‬جلــد املدعــى عليــه ثمانــن جلــدة‬\n      ‫حــد املســكر ‪-3‬تعزيــر املدعــى عليــه بســجن مــدة ثــاث ســنوات وجلــده‬\n      ‫خمســن جلــدة تتكــرر عليــه ســت مــرات وتغرميــه ألــف ريــال ومنعــه مــن‬\n      ‫الســفر بعــد خروجــه مــن الســجن مــدة ثــاث ســنوات ومصــادرة ســيارته‬\n      ‫املذكــورة يف الدعــوى ومصــادرة هاتفــه اجلــوال وعــدم صــرف نفــس‬\n      ‫الشــريحة لــه و إلزامــه بتســليم املبلــغ احلكومــي وقــدره ســتمائة ريــال‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم قناعتــه ورغبتــه‬\n      ‫رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وقــرر‬\n\n\n‫‪311‬‬\n\f‫املدعــى عليــه قناعتــه وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره يف‬\n                                                              ‫متــام الســاعة ‪. 11 : 45‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن ‪1434/6/12‬ه ـ فتحــت اجللســة‬\n‫يف متــام الســاعة ‪ 10 : 00‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم يف‬\n‫‪1434/5/13‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1434/6/12‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم‬\n‫وتاريــخ ‪1434/3/28‬ه ـ املقيــدة لــدى احملكمــة برقــم ………‬\n‫وتاريــخ ‪1434/4/7‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ...........‬املســجل برقــم وتاريــخ ‪1434/3/24‬ه ـ‬\n‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ ......... /‬يف قضيــة مخــدرات وقــد‬\n‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                            ‫حرريف‪1434/5/12‬ه ـ‬\n\n\n\n\n                                                                                          ‫‪312‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":307,"source_page_end":312,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f52df4531a8b028ce69c2f4b046cdf3de0b1a3e22d1089ef685395e889adaf58","normalized_text_hash":"892deaca29ec44496535fdf53e8c9f63831f0751dfe443787533e6a1759ac325","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p307-34171068"},{"id":"8ed987fc-6ad5-5aa0-875d-05b0323c7a14","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -تستر -توجيه شبهة -تعزير بالشبهة -تعزير بالتهمة -تعزير بالسجن واجللد -تعزير باملصادرة- تعزير بإلغاء شريحة جوال -تسليم حبوب محظورة -استالم حبوب","document_number":"34232696","case_number":"34161758","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/6","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -تستر -توجيه شبهة -تعزير بالشبهة -تعزير بالتهمة -تعزير بالسجن واجللد -تعزير باملصادرة- تعزير بإلغاء شريحة جوال -تسليم حبوب محظورة -استالم حبوب","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34232696:‬تاريخه ‪1434/6/6:‬هـ‬\n                        ‫رقم الدعوى ‪34161758:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34273141‬تاريخه‪1434/07/19:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة‪ -‬تســتر‪ -‬توجيــه شــبهة‪ -‬تعزيــر‬\n      ‫بالشــبهة‪ -‬تعزير بالتهمة‪ -‬تعزير بالســجن واجللد ‪ -‬تعزير باملصادرة‪-‬‬\n      ‫تعزيــر بإلغــاء شــريحة جــوال‪ -‬تســليم حبــوب محظــورة‪ -‬اســتالم حبــوب‬\n                                                                    ‫محظــورة‬\n\n\n\n\n                       ‫املادة ‪ 53‬من نظام مكافحة املخدرات و املؤثرات العقلية‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتوجيــه االتهــام لــه بترويــج‬\n      ‫حبــوب اإلمفيتامــن وتســتره علــى املصــدر الــذي حصــل منــه علــى‬\n      ‫احلبــوب احملظــورة ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه و احلكــم‬\n      ‫عليــه بالســجن واجللــد والغرامــة و منعــه مــن الســفر بعــد انتهــاء عقوبتــه و‬\n      ‫تعزيــره لقــاء تســتره علــى مصــدر مــا ضبــط و مصــادرة الهاتــف اجلــوال و‬\n      ‫إلغــاء الشــريحة و التــزام املدعــى عليــه بــرد املبلــغ املرقــم ‪ ،‬حيــث أنــه مت‬\n      ‫القبــض علــى املدعــى عليــه بعــد ورود معلومــات ســرية لــدى املكافحــة‬\n      ‫تفيــد بوجــود شــخص يقــوم بالتوســط يف ترويــج احلبــوب احملظــورة و‬\n      ‫يتواجــد علــى جوالــه و اســتعد املصــدر بالشــراء املباشــر مــن املــروج و‬\n      ‫مت متكــن املصــدر مــن االتصــال بهاتــف جــوال املعنــي باإلخباريــة و‬\n\n‫‪313‬‬\n\f‫طلــب منــه كميــة حبــوب مقابــل مبلــغ مالــي فأبــدى املتهــم موافقتــه‬\n‫وطلــب منــه احلضــور وعندهــا مت تزويــد املصــدر مببلــغ مرقــم ومت‬\n‫تفتيــش املصــدر تفتيشـ ًا دقيقـ ًا وجــرى تكليــف أحــد أفــراد املكافحــة‬\n‫مبرافقــة املصــدر ملشــاهدة عمليــة االســتالم والتســليم وحضــر املتهــم و‬\n‫قابــل املصــدر يف املــكان املتفــق عليــه وســلم املصــدر للمتهــم مبلــغ مالــي‬\n‫مرقــم ثــم غــادر املتهــم نصــف ســاعة ثــم حضــر وســلم للفــرد املكلــف‬\n‫بالشــراء أربــع حبــات يشــتبه أن تكــون احلبــوب احملظــورة‪ ،‬كمــا أنكر‬\n‫املدعــى عليــه الدعــوى‪ ،‬إحضــار املدعــى العــام البينــة غيــر مكتملــة‪،‬‬\n‫بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن‬\n‫واجللــد ومصــادرة الهاتــف اجلــوال املســتخدم يف اجلرميــة وإدخــال قيمتــه يف‬\n‫حســاب مكافحــة املخــدرات وإلغــاء الشــريحة املضبوطــة وعــدم صرفها‬\n               ‫للمدعــى عليــه وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34161758‬وتاريــخ‬\n‫‪ 1434/04/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34860652‬وتاريــخ‬\n‫‪ 1434/04/08‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/04/13‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 09 : 45‬وفيهــا حضــر املدعــي العــام ‪ ..............‬مبوجــب‬\n‫خطــاب التكليــف مــن مرجعــه رقــم ‪ ..............‬يف ‪1434/1/24‬هـ وادعى‬\n‫علــى احلاضــر ‪ : ..................... /‬ســعودي بالســجل املدنــي ‪....................‬‬\n‫حيــث انــه بتاريــخ ‪1434/1/14‬ه ـ وردت معلومــات ســريه لدى مكافحة‬\n\n                                                                                          ‫‪314‬‬\n\f      ‫املخــدرات بالعاصمــة املقدســة تفيــد عــن وجــود شــخص يقــوم يف‬\n      ‫بالتوســط يف ترويــج احلبــوب احملظــورة بشــارع ‪ ..............‬حــارة ‪..............‬‬\n      ‫ويتواجــد علــى رقــم جــوال (‪ )..............‬واســتعد املصــدر بالشــراء املباشــر‬\n      ‫مــن املــروج ومت متكــن املصــدر مــن االتصــال بهاتــف جــوال املعنــي‬\n      ‫باإلخباريــة وطلــب منــه كميــة مــن احلبــوب احملظــورة مببلغ وقــدره(‪)100‬‬\n      ‫مائــة ريــال فأبــدى املعنــي باإلخباريــة موافقتــه وطلــب منــه احلضــور إليــه‬\n      ‫بشــارع ‪ ..............‬عندهــا مت تزويــد املصــدر مببلــغ مرقــم وقــدره(‪)100‬‬\n      ‫مائــة ريــال بعــد تفتيشــه تفتيشــا دقيقــا ودفعــه حتــت أنظــار الفرقــة‬\n      ‫وجــرى تكليــف الفــرد رقــم (‪ )..............‬مبرافقــة املصــدر ملشــاهدة‬\n      ‫عمليــة االســتالم والتســليم ومت دفــع املصــدر والفــرد إلــى املوقــع احملــدد‬\n      ‫مــن قبــل الوســيط ومت مشــاهدت املعنــي باإلخباريــة مترجل علــى األقدام‬\n      ‫واســتلم املبلــغ مــن املصــدر واختفــى عــن األنظــار ملــدة نصــف ســاعة‬\n      ‫وبعدهــا حضــر وأســتلم املصــدر والفــرد املكلــف بــدور املشــتري عــدد‬\n      ‫(‪ )4‬أربعــة حبــات يشــتبه أن تكــون مــن حبــوب الكبتاجــون احملظــورة‬\n      ‫ومت مشــاهدت املعنــي باإلخباريــة علــى ســيارة مــن نــوع ‪ ....‬ومت القبــض‬\n      ‫عليــه واتضــح انــه املدعــى عليــه وعثــر معــه علــى جهــاز اجلــوال الــذي مت‬\n      ‫التنســيق عليــه يف عمليــة الشــراء واتضــح أنــه ويحمــل الرقــم املصنعــي‬\n      ‫(‪ )..............‬ولــم يعثــر معــه علــى املبلــغ احلكومــي املرقــم‪،‬ومت التعــرف‬\n      ‫عليــه مــن قبــل الفــرد مت حجــز املضبوطــات جهــاز اجلــوال املســتخدم‬\n      ‫يف اجلرميــة وباســتجواب املدعــى عليــه أفــاد بــان اجلــوال الــذي يحمــل‬\n      ‫الرقــم املصنعــي (‪ )..............‬والشــريحة رقــم (‪ )..............‬عائــد لــه وحتــت‬\n      ‫تصرفــه شــخص ًا وقــد اثبــت التقريــر الكيميائــي الشــرعي (‪..............‬ـ)‬\n      ‫ايجابيــة املــادة املروجــة املضبوطــة ملــادة االمفيتامني احملظــورة واملدرجة‬\n\n\n‫‪315‬‬\n\f‫باجلــدول رقــم (‪ )2‬فئــه (ب) امللحــق بنظــام مكافحة املخدرات واملؤثرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بترويــج (‪ )4‬أربــع‬\n‫حبــات مــن احلبــوب حتتــوي علــى مــادة االمفيتامــن عــن طريــق البيــع‬\n‫احملــرم شــرع ًا واملجــرم نظامـ ًا وفقـ ًا للفقــرة( الثانيــة) مــن املــادة( الثالثــة)‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم‬\n‫امللكــي الكــرمي رقــم (م‪ )39/‬يف ‪1426/7/8‬ه ـ وتســتره علــى املصــدرة‬\n‫الــذي حصــل منــه علــى احلبــوب احملظــورة وذلــك لألدلــة والقرائــن التاليــة‬\n‫ا يف محضــر‬     ‫‪ -1‬مــاورد يف محضــر القبــض والتفتيــش املنــوه عنــه تفصيـ ً‬\n                                 ‫االســتدالل املرفــق بالقضيــة لفــه (‪ )1‬ص (‪)12‬‬\n‫‪ -2‬مــاورد بالتقريــر الكيميائــي الشــرعي املرفــق بالقضيــة لفــه( ‪)17‬‬\n‫وحيــث إن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا مبوجــب‬\n‫نظــام مكافحــة املخــدرات الصــادر باملرســوم امللكــي رقــم(م‪)39/‬‬\n‫بتاريــخ ‪1426/7/8‬ه ـ املشــار إليــه بعقوبتــه األصليــة والتكميليــة لــذا‬\n‫أطلــب إثبــات أدانتــه مبــا أســند إليــه واحلكــم عليــه بالعقوبــات التاليــة‬\n‫‪-1‬بالســجن واجللــد والغرامــة لقــاء ماأســند إليــه وفق ـ ًا للفقــرة(‪)1‬‬\n‫مــن املــادة (‪)38‬مــن نظــام املخــدرات واملؤثــرات العقليــة وأن تكــون‬\n‫عقوبتــه بحدهــا األعلــى لقــاء ترويجــه للحبــوب احملظــورة وفقـ ًا لتعميــم‬\n‫صاحــب الســمو امللكــي ولــي العهــد وزيــر الداخليــة رقــم(‪)8346‬‬\n‫تاريخ‪1427/2/10-9‬هـ‪-2..‬منعــه مــن الســفر خلــارج البــاد بعــد أنتهــا‬\n‫تنفيــذ عقوبتــه وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة‬\n‫املخــدرات املشــار إليــه ‪-3‬تعزيــرة لقــاء تســتره علــى مصــدرة يف احلصــول‬\n\n\n                                                                                              ‫‪316‬‬\n\f      ‫علــى املــواد احملظــورة وفقـ ًا لتعميــم معالــي رئيــس الهيئــة رقــم( ‪)15596‬‬\n                                                               ‫تاريــخ ‪1433/5/4‬هــ‪.‬‬\n      ‫‪-4‬مصــادرة الهاتــف اجلــوال ذو الرقــم املصنعــي (‪ )..............‬للشــريحة‬\n      ‫رقــم (‪ )..............‬وفق ـ ًا للفقــرة األولــى مــن املــادة رقــم (‪ )53‬مــن نفــس‬\n      ‫النظــام والنــص يف القــرار الشــرعي علــى إدخــال قيمتــه ملؤسســة النقــد‬\n      ‫العربــي الســعودي حلســاب املديريــة العامــة ملكافحــة املخــدرات اســتناد ٍا‬\n      ‫لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )40656‬وتاريــخ‬\n      ‫‪1430/6/23‬ه ـ وإلغــاء الشــريحة وفقـ ًا لتعميــم ســمو النائــب الثاني وزير‬\n                               ‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10 -9‬هــ‪.‬‬\n      ‫‪-5‬إلــزام املدعــى عليــه بــرد املبلــغ املرقــم قــدره(‪ )100‬ريــال إلدارة‬\n      ‫مكافحة املخدرات بالعاصمة املقدســة اســتناد ًا لتعميم وزير الداخلية‬\n             ‫رقــم ‪ 65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه اجــاب بقولــه ماذكــره املدعــي العــام غيــر صحيح‬\n      ‫ولــم أروج املخــدرات ولــم أســلم ولــم أســتلم شــيئا هــذه إجابتــي وقــال‬\n      ‫املدعــي العــام الصحيــح ماذكــرت ولــدي البينــة ســأحضرها يف اجللســة‬\n      ‫القادمــة لــذا رفعــت اجللســة ويف يــوم االحــد املوافــق ‪1434/4/21‬ه ـ‬\n      ‫افتتحــت اجللســة وحضــر فيهــا املدعــي العــام واملدعــى عليــه ولــم يحضــر‬\n      ‫املدعــي العــام بينتــه لــذا رفعــت اجللســة حلــن احضارهــا ويف يــوم اإلثنــن‬\n      ‫املوافق‪1434/05/27‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا حضــر‬\n      ‫املدعــي العــام واملدعــى عليــه وبســؤال املدعــي العــام عــن بينتــه أحضــر‬\n      ‫للشــهادة ‪..............‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪..............‬‬\n      ‫فشــهد بقولــه انــه مت االتصــال علــى املدعــى عليــه وســمعته يوافــق‬\n      ‫صراحــة علــى بيــع حبــوب االمفيتامــن احملظــورة مبائــة ريــال وطلــب مــن‬\n\n\n‫‪317‬‬\n\f‫املصــدر احلضــور إليــه يف شــارع ‪..............‬فتوجــه املصــدر وزميلــه الــى‬\n‫املوقــع وانتهــت مهمتــي عنــد ذلــك هــذه شــهادتي كمــا حضــر للشــهادة‬\n‫‪..............‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪..............‬فشــهد بقولــه‬\n‫انــه مت االتصــال علــى املدعــى عليــه وســمعته يوافــق صراحــة علــى بيــع‬\n‫حبــوب اإلمفيتامــن احملظــورة مبائــة ريــال وطلــب مــن املصــدر احلضــور‬\n‫اليــه يف شــارع ‪..............‬فرافقــت املصــدر وقابلنــا املدعــى عليــه ورأيــت‬\n‫املصــدر يســلم املدعــى عليــه مائــة ريــال ثــم غــاب املدعــى عليــه قليــا‬\n‫ورجــع وســلم املصــدر اربــع حبــات إمفيتامــن وكان احلــي مكشــوفا فلم‬\n‫يشــاهده غيــري هــذه شــهادتي وقــال املدعــى عليــه مــا ذكــره الشــهود‬\n‫غيــر صحيــح وال اعرفهــم ثــم جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫املرفــق باملعاملــة لفــة ‪ 17‬فوجدتــه يتضمــن احتــواء املضبوطــات علــى‬\n‫اإلمفيتامــن احملظــور كمــا لــم أجــد للمدعــى عليــه ســوابق فرفعــت‬\n‫اجللســة للتأمــل ويف يــوم االثنــن املوافــق ‪1434/6/5‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي العــام واملدعــى عليــه وقــد جــرى تأمــل القضيــة‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلــى إنــكار املدعــى عليــه‬\n‫لدعــوى املدعــي العــام وبنــاء علــى شــهادة البينــة العادلــة لســبق تزكيتهــم‬\n‫يف شــهادة ســابقة وحيــث لــم تكتمــل البينــة علــى الترويــج ألنــه لــم‬\n‫يشــاهد عمليــة الترويــج والتســليم واالســتالم ســوى الشــاهد الثانــي فــا‬\n‫تنطبــق علــى املدعــى عليــه املــواد ‪38‬و‪ 56‬مــن نظــام مكافحــة املخــدرات‬\n‫ونظــرا الكتمــال البينــة علــى االتصــال وســماع املكاملــة ولصراحــة‬\n‫شــهادة الشــاهد الثانــي وبنــاء علــى املــادة ‪ 53‬مــن نظــام مكافحــة‬\n‫املخــدرات لــذا فــإن الشــبهة القويــة تتجــه للمدعــى عليــه بإدانتــه مبــا‬\n‫أســند إليــه مــن ترويــج أربــع حبــات مــن حبــوب اإلمفيتامــن احملظــورة‬\n\n\n                                                                                       ‫‪318‬‬\n\f      ‫عــن طريــق البيــع وتســتره علــى مصــدر احلبــوب وحكمــت بتعزيــره علــى‬\n      ‫ذلــك بالســجن مــدة ســنة ونصــف ابتــداء مــن تاريــخ التوقيــف وجلــده مائــة‬\n      ‫وســتني جلــدة مفرقــة علــى أربــع دفعــات كل دفعــة أربعــون جلــدة بــن‬\n      ‫كل دفعــة وأخــرى شــهر كمــا ثبــت لــدي إدانــة املدعــى عليــه باســتخدام‬\n      ‫هاتفــه اجلــوال املذكــور للترويــج وحكمــت مبصــادرة الهاتــف اجلــوال ذو‬\n      ‫الرقــم املصنعــي (‪ )..............‬للشــريحة رقــم (‪ )..............‬وإدخــال قيمتــه‬\n      ‫مبؤسســة النقــد العربــي الســعودي حلســاب املديريــة العامــة ملكافحــة‬\n      ‫املخــدرات وإلغــاء الشــريحة املضبوطــة وعــدم صرفهــا للمدعــى عليــه‬\n      ‫وصرفــت النظــر عمــا ســوى ذلــك وبعــرض احلكــم علــى املدعــى عليــه‬\n      ‫قنــع بــه وقــد عــارض املدعــي العــام وطلــب االســتئناف بالئحــة فأجيــب‬\n      ‫لطلبــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمد وآلــه وصحبه‪.‬‬\n                                                              ‫حــرر يف ‪1434/6/5‬هــ‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد ثــم عــادة املعامة مــن محكمة االســتئناف وبرفقها‬\n      ‫القرار رقم ‪ 34273141‬يف ‪1434/7/19‬هـ املتضمن املوافقة والتصديق‬\n      ‫علــى احلكــم وبــاهلل التوفيــق ‪.‬قاضــي اســتئناف‪ ............../‬ختــم‪ .‬توقيــع‪.‬‬\n      ‫قاضــي اســتئناف‪............../‬ختم‪ .‬توقيــع‪ .‬رئيــس اســتئناف‪............../‬ختم‪.‬‬\n                             ‫توقيــع لــذا جــرى احلاقــه واثباته حــرر يف ‪1434/8/3‬هـ‬\n\n\n\n\n‫‪319‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":313,"source_page_end":319,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d50174ca71ae27907c7ab2410d23a7f4d74ff682774619c769d68ae910e2d30","normalized_text_hash":"0d9020090c11563fe05064f8d850106adabbf60a66096fc81b3c181ad6d53a68","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p313-34232696"},{"id":"dfebab59-e74a-5274-bcab-bb564cb5da12","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -نقل بقصد الترويج -قات -تستر على مصدر الكمية - الهروب -املدعى عليه أجنبي -التعزير بالسجن واجللد واملصادرة والتوصية باإلبعاد .","document_number":"34184623","case_number":"34163865","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/10","year":"1434","subject":"مخدرات -نقل بقصد الترويج -قات -تستر على مصدر الكمية - الهروب -املدعى عليه أجنبي -التعزير بالسجن واجللد واملصادرة والتوصية باإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34184623:‬تاريخه‪1434/04/10 :‬هـ‬\n                   ‫رقم الدعوى‪34163865:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34203510‬تاريخه‪1434/05/01:‬هـ‬\n\n\n‫مخــدرات ‪ -‬نقــل بقصــد الترويــج ‪ -‬قــات ‪ -‬تســتر علــى مصــدر الكميــة ‪-‬‬\n‫الهــروب ‪ -‬املدعــى عليــه أجنبــي ‪ -‬التعزيــر بالســجن واجللــد واملصــادرة‬\n                                                      ‫والتوصيــة باإلبعــاد ‪.‬‬\n\n\n\n‫‪ -1‬املــادة الثالثــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬يف ‪1374‬ه ـ املعــدل‬\n‫بقــراري وزيــر الداخليــة رقــم (‪ )2057‬لعــام ‪ 1404‬ه ـ ورقــم ‪ 3818‬لعــام‬\n                                                                      ‫‪1410‬هـ‪.‬‬\n‫‪-2‬األمــر الســامي الكــرمي رقــم (‪ )59633‬يف ‪1433/12/9‬ه ـ القاضــي‬\n ‫باســتثناء عقوبــات قضايــا القــات مــن نظــام مكافحــة املخــدرات‪.‬‬\n‫‪ -3‬تعميــم صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس‬\n             ‫الــوزراء وزيــر الداخليــة رقــم (‪ )9798‬يف ‪1428/2/10‬ه ـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بنقــل قــات بقصــد الترويــج‬\n‫وطلــب إثبــات مــا أســند إليــه وتعزيــره ‪ ،‬وتعزيــره لقــاء هروبــه ومصــادرة‬\n‫جوالــه مــع إلغــاء الشــريحتني ‪،‬حيــث لــم يتوقــف املدعــى عليــه عنــد نقطة‬\n‫التفتيــش فجــرت مطاردتــه والقبــض عليــه وبتفتيــش الســيارة ضبــط‬\n‫بداخلهــا كميــة مــن نبــات أخضــر يشــتبه بأنــه قــات وأثبــت التقريــر‬\n\n                                                                                    ‫‪320‬‬\n\f      ‫الكيمائــي الشــرعي إيجابيــة العينــة لنبــات القــات احملظــور وصــادق‬\n      ‫املدعــى عليــه علــى الدعــوى ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n      ‫عليــه بالســجن ثــاث ســنوات تعزيــرا وغرامــة ماليــة قدرهــا عشــرة آالف‬\n      ‫ريــال وجلــده خمســون جلــدة مفرقــة علــى دفعــات ومصــادرة اجلوالــن‬\n      ‫وإلغــاء شــرائحهما وإبعــاده مــن البــاد وقنــع املدعــى عليــه واعتــرض‬\n      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬  ‫املدعــي العــام بــدون الئحــة ُ‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 34163865‬وتاريــخ ‪ 1434/04/09‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 34871500‬وتاريــخ ‪ 1434/04/09‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافــق‪ 1434/04/10‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫‪ 09 : 30‬وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم ‪.....‬‬\n      ‫يف ‪1433/3/22‬ه ـ وادعــى علــى احلاضــر معــه الســجني ‪ ..... /‬ـ ـ البالـ ــغ‬\n      ‫م ـ ــن العمـ ــر ـ ـ (‪ )29‬عــامـ ـ ـ ـ ًا ـ ( أجنبــي اجلنســية) ـ ب ـمــوجـ ــب البطاقــة‬\n      ‫البديلـ ـ ــة رق ــم ( ‪ ).....‬وتاري ــخ ‪1434/2/26‬هـ الصــادرة مــن مكافح ــة‬\n      ‫املخـ ــدرات بصامطـ ــة ( متـ ــزوج ـ متعلم ـ عامل ) مودع بشعبـ ــة السجـ ــن‬\n      ‫الع ـ ــام بجـ ــازان ( قسـ ــم سجـ ــن أحـ ــد املســارحـ ـ ــة ) مبــوجـ ـ ــب أمـ ــر‬\n      ‫التمــديـ ـ ــد واإلحالـ ـ ــة قـ ــم ( ‪ ).....‬وتاريخ ‪1434/3/4‬هـ كون جرميته من‬\n      ‫اجلرائــم املوجبــة للتوقيــف اســتناد ًا للقــرار الــوزاري رقــم (‪ ) 1900‬وتاريــخ‬\n      ‫‪1428/7/9‬ه ـ ويعتبــر إيقافــه مــن تاريخ القبض عليه يف ‪1434/2/26‬هـ‬\n      ‫إنــه يف متــام الســاعة اخلامســة والنصــف مــن صبــاح يــوم الثالثــاء املوافــق‬\n\n‫‪321‬‬\n\f‫‪1434/2/26‬ه ـ وأثنــاء قيــام إحــدى دوريــات شــرطة صامطــة بواجبهــا‬\n‫وحتديــد ًا عنــد إشــارة ‪.....‬مت االشــتباه يف ســيارة قادمــة مــن الشــرق إلــى‬\n‫الغــرب مــن نــوع تويوتــا ســنة الصنــع ( ‪ 2011‬م ) حتمــل اللوحــة رقــم (‪).....‬‬\n‫تعــود ملكيتهــا للشــركة ‪ (.....‬لــم يوجــه لــه االتهــام لكــون الســيارة‬\n‫مســروقة ومعمــم عنهــا بتاريــخ ‪1434/2/23‬ه ـ ) جــرت املخاطبــة بذلــك‬\n‫بقيـ ـ ـ ــادة ( املدعــى عليــه ) وباســتيقافه رفــض التوقــف وجــرت مطاردتــه‬\n‫حتــى وصــل طريــق ‪.....‬ومت القبــض عليــه وبتفتيشــها ضبــط بداخلهــا‬\n‫كميــة مــن نبــات أخضــر يشــتبه أن تكــون مــن نبــات القــات احملظــور‬\n‫بلــغ وزنهــا ( ‪ 306‬كجــم ) ثالثمائــة وســتة كيلــو جرامـ ًا وضبــط معــه‬\n‫جــوال مــن نــوع يحمــل الرقــم املصنعــي رقــم ( ‪ ).....‬مــع شريحـ ـ ــة حتمـ ـ ــل‬\n‫الرقـ ـ ـ ــم ( ‪ ) .....‬وجـ ـ ــوال آخـ ـ ــر مــن ن ـ ــوع يحم ـ ـ ــل ال ــرقـ ـ ـ ـ ــم ( ‪ ).....‬مــع‬\n‫شــريحة ( ‪ ، ).....‬أثبــت التقريــر الكيميائــي الشــرعي رقــم ( ‪.....‬لعــام‬\n‫‪1434‬ه ـ ) الصــادر مــن مركــز الســموم والكيميــاء الشــرعية الطبيــة‬\n‫بجــازان إيجابيــة العينــة املرســلة مــن الكميــة املضبوطــة لنبــات القــات‬\n‫احملظــور املــدرج يف اجلــدول رقــم ( ‪ ) 4‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ .‬باســتجواب ( املدعــى عليــه) بعــد مواجهتــه بالتهمــة‬\n‫املنســوبة إليــه وبأقوالــه يف محضــر ســماع األقــوال أقــر بنقــل الكميــة‬\n‫البالــغ وزنهــا ( ‪306‬كجــم ) ثالثمائــة وســتة كيلــو جــرام مــن نبــات‬\n‫القــات احملظــور لشــخص اســمه ‪.....‬امللقــب ب‪ (.....‬متــت املخاطبــة بشــأنه)‬\n‫مــن بعــد نقطــة ‪.....‬إلــى ‪.....‬مببلــغ ( ‪ ) 500‬خمســمائة ريــال لــم يســتلمها‬\n‫وأنــه هــو الشــخص الــذي ســلمه الســيارة وأقــر باســتخدام جواليــه االثنني‬\n‫يف اجلرميــة وبهروبــه مــن رجــال األمــن للخــوف وبــأن الســابقة املوجــودة‬\n‫يف كــرت البصمــات تعــود لــه واالســم املذكــور فيهــا اســم مســتعار‬\n\n\n                                                                                                           ‫‪322‬‬\n\f      ‫لــه خلوفــه علــى معاملتــه ‪.‬وقــد أســفر التحقيــق مــع ( املدعـ ــى عليــه) عـ ــن‬\n      ‫توجيـ ــه االتهـ ــام إليــه بنقــل مــا وزنــه ( ‪ 306‬كجــم ) ثالثمائــة وســتة‬\n      ‫كيلــو جرام ـ ًا مــن نبــات القــات احملظــور بقصــد الترويــج ‪ ،‬املجــرم‬\n      ‫مبوجــب الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة وبتســتره علــى مصــدر الكميــة ومبحاولتــه الهــرب‬\n                                ‫مــن رجــال األمــن وذلــك لألدلــة والقرائــن التاليــة ‪:‬ـ‬\n      ‫‪1‬ـ مــا جــاء يف إقــراره املنــوه عنــه املــدون بدفتــر التحقيــق ص ( ‪ ) 4‬املرفــق‬\n                                                                            ‫لفــة رقــم ( ‪. ) 34‬‬\n      ‫‪ 2‬ـ محضــر القبــض والتفتيــش املنــوه عنــه مبلــف ضبــط إجــراءات‬\n                                  ‫االســتدالل ص ( ‪ ) 12‬املرفــق لفــة رقــم ( ‪. ) 1‬‬\n             ‫‪ 3‬ـ التقرير الكيميائي الشرعي املنوه عنه املرفق لفة رقم ( ‪. ) 25‬‬\n      ‫وبالبحــث عــن ســوابقه عثــر لــه علــى ســابقة واحــدة وهــي اعتــداء باســم‬\n      ‫‪ ....‬وحيــث إن مــا أقــدم عليــه ( املدعــى عليــه ) فعــل محــرم شــرع ًا‬\n      ‫ومعاقــب عليــه نظام ـ ًا مبوجــب قــرار مجلــس الــوزراء رقــم ( ‪ ) 11‬لعــام‬\n                                   ‫‪1374‬ه ـ ومــا حلــق بــه مــن تعديــات لــذا أطلــب ‪:‬‬\n      ‫‪1‬ـ إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره علــى ضــوء املــادة (‬\n      ‫الثالثــة ) مــن القــرار الــوزاري املشــار إليــه أعــاه إنفــاذ ًا لألمــر الســامي‬\n                               ‫الكــرمي رقــم ( ‪ ) 59633‬وتاريــخ ‪1432/12/9‬ه ـ ‪.‬‬\n            ‫‪2‬ـ احلكم بتعزيره شرع ًا لقاء هروبه من رجال األمن أثناء القبض ‪.‬‬\n              ‫‪3‬ـ احلكم مبصادرة جهاز جوال من نوع يحمل الرقم املصنعي رقم‬\n      ‫(‪ )......‬وجــوال آخــر مــن نــوع يحمــل الرق ـ ـ ـ ــم ( ‪ ).....‬مــع إلغــاء الشــريحتني‬\n      ‫حتمــان الرق ـ ـ ــم ( ‪ ) .....‬والرقــم ( ‪ ) .....‬العائــدة ( للمدعــى عليــه ) وعــدم‬\n      ‫صــرف تلــك الشــريحتني لــه اســتناد ًا لتعميــم صاحــب الســمو امللكــي‬\n\n\n‫‪323‬‬\n\f‫النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة ( رحمــه اهلل )‬\n‫رقــم ( ‪ ) 9798‬وتاريــخ ‪9‬ـ ‪1428/2/10‬ه ـ واهلل املوفــق وبعــرض مــا جــاء‬\n‫يف دعــوى املدعــي العــام علــى املدعــى عليــه صــادق علــى صحــة واقعــة‬\n‫القبــض وأنــه هــو مــن كان يقــود ســيارة مــن نــوع والتــي ضبطــت بهــا‬\n‫كميــة القــات والبالــغ وزنهــا( ‪ 306‬كجــم ) ثالثمائــة وســتة كيلــو‬\n‫جرامـ ًا مــن نبــات القــات احملظــور و أن قصــده نقــل الكميــة املضبوطــة‬\n‫لشــخص اســمه ‪.....‬امللقــب ب‪.....‬مــن بعــد نقطــة ‪.....‬إلــى ‪.....‬مببلــغ ( ‪)500‬‬\n‫خمســمائة ريــال لــم يســتلمها وأنــه هــو الشــخص الــذي ســلمه الســيارة‬\n‫وأقــر باســتخدام جواليــه االثنــن يف اجلرميــة وبهروبــه مــن رجــال األمــن‬\n‫للخــوف وبــأن الســابقة املوجــودة يف كــرت البصمــات تعــود لــه واالســم‬\n‫املذكــور فيهــا اســم مســتعار لــه خلوفــه علــى معاملتــه هكــذا أجــاب‬\n‫وباالطــاع علــى محضــر القبــض و التحقيــق وجــد مطابــق ملــا جــاء يف‬\n‫الئحــة الدعــوى وباالطــاع علــى التقريــر الكيميائــي لفــة رقــم (‪)25‬‬\n‫وجــد إيجابيــة العينــة املرســلة منــه ملــادة القــات احملظــور وباالطــاع علــى‬\n‫صحيفــة الســوابق عثــر لــه علــى ســابقة اعتــداء فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة وحيــث اعتــرف املدعــى عليــه بترويــج الكميــة أعــاه‬\n‫عــن طريــق النقــل مقابــل مبلــغ مالــي وحيــث إن مــا أقــدم عليــه فعــل‬\n‫محــرم ومعاقــب عليــه نظامـ ًا فقــد ثبــت لــدي إدانــة املدعــى عليــه بترويــج‬\n‫مــا وزنــه ( ‪ 306‬كجــم ) ثالثمائــة وســتة كيلــو جرامـ ًا مــن نبــات القــات‬\n‫احملظــور عــن طريــق النقــل مقابــل مبلــغ مالــي وحكمــت عليــه تعزيــر ًا‬\n‫بالســجن ملــدة ثــاث ســنوات اعتبــارا مــن تاريــخ توقيفــه وبغرامــة ماليــة‬\n‫قدرهــا عشــرة آالف ريــال اســتنادا للمــادة الثالثــة مــن قــرار مجلــس‬\n‫الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ املعــدل بقــراري وزيــر الداخليــة رقــم‬\n\n\n                                                                                      ‫‪324‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":320,"source_page_end":324,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3628b288564eea3c029f159a44af584aece658f8150c5a49530b29c179da9ac2","normalized_text_hash":"ba852f29cf68bcc61c354cb9473f3b8bf8774cf75bcf69d848b996f00fb5e089","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p320-34184623"},{"id":"d2fc31f6-c333-5af6-adb4-05e6fdbc6386","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حشيش مخدر -الوساطة يف ترويج حشيش مخدر -حيازة حشيش مخدر -تعاطي حشيش مخدر -تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -تعزير بعدم صرف شريحة جوال للمدعى عليه -إقامة حد املسكر .","document_number":"34196192","case_number":"34165739","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/23","year":"1434","subject":"مخدرات -ترويج حشيش مخدر -الوساطة يف ترويج حشيش مخدر -حيازة حشيش مخدر -تعاطي حشيش مخدر -تعزير بالسجن واجللد والغرامة -تعزير باملنع من السفر -تعزير باملصادرة -تعزير بعدم صرف شريحة جوال للمدعى عليه -إقامة حد املسكر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34196192 :‬تاريخه ‪1434/04/23 :‬هـ‬\n                          ‫رقم الدعوى‪34165739 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34223687‬تاريخه‪1434/05/27 :‬هـ‬\n\n\n       ‫مخدرات ‪ -‬ترويج حشــيش مخدر ‪ -‬الوســاطة يف ترويج حشــيش مخدر‬\n       ‫‪ -‬حيــازة حشــيش مخــدر ‪ -‬تعاطــي حشــيش مخــدر ‪ -‬تعزيــر بالســجن‬\n       ‫واجللــد والغرامــة ‪ -‬تعزيــر باملنــع مــن الســفر ‪ -‬تعزير باملصــادرة ‪ -‬تعزير‬\n            ‫بعــدم صــرف شــريحة جــوال للمدعــى عليــه ‪ -‬إقامــة حــد املســكر ‪.‬‬\n\n\n\n\n       ‫‪ -1‬الفقــرة ‪ 2‬مــن املــادة ‪ 3‬والفقــرة ‪ 1‬مــن املــادة ‪ 38‬والفقــرة ‪ 1‬مــن املــادة‬\n       ‫‪ 53‬والفقــرة ‪ 1‬مــن املــادة ‪ 56‬و الفقــرة ‪ 1‬مــن املــادة ‪ 60‬والفقــرة ‪ 1‬مــن‬\n                      ‫املــادة ‪ 62‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n       ‫‪ -2‬ذكــر شــيخ اإلســام ابــن تيميــة يف الفتــاوى ( والصحيــح إن‬\n       ‫احلشيشــة مســكرة كالشــراب وان آكلهــا يحــد منهــا فهــي خمــر )‪-‬ج‪29‬‬\n                                                                                  ‫ص ‪135‬‬\n       ‫‪-3‬ذكــر شــيخ اإلســام بــن تيميــة رحمــه اهلل ( وفيهــا مــن املفاســد مــا‬\n       ‫ليــس يف اخلمــر وإن كان يف اخلمــر مفســدة ليســت فيهــا وهــي احلــدة‬\n       ‫فهــي بالتحــرمي أولــى مــن اخلمــر ألن ضــرر آكل احلشــيش علــى نفســه‬\n       ‫أشــد مــن ضــرر اخلمــر وضــرر شــارب اخلمــر علــى النــاس أشــد إال أنــه‬\n       ‫يف هــذه األزمــان لكثــرة آكل احلشــيش صــار الضــرر الــذي فيهــا علــى‬\n                                ‫النــاس أعظــم مــن اخلمــر ) الفتــاوى ج‪ 29‬ص ‪135‬‬\n\n\n\n‫‪327‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا باتهامهــا ببيــع األول للحشــيش‬\n‫املخــدر بقصــد االجتــار ‪ ،‬وتوســط املتهــم الثانــي يف بيــع احلشــيش املخــدر‬\n‫بقصــد االجتــار وحيــازة األول للحشــيش املخــدر بقصــد التعاطــي‬\n‫والترويــج وتعاطيهمــا للحشــيش املخــدر وطلــب املدعــي العــام إثبــات‬\n‫إدانتهمــا مبــا أســند إليهمــا و احلكــم عليهمــا بالعقوبــة الــورادة بالفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة‬\n‫املخــدرات و املؤثــرات العقليــة ومنعهمــا مــن الســفر ومصــادرة الهاتــف‬\n‫اجلــوال العائــد للمدعــى عليــه األول و الهاتــف اجلــوال العائــد للمدعــى‬\n‫عليــه الثانــي الســتخدامهما يف الترويــج و إســقاط شــريحة الهاتفــن و‬\n‫عــدم صرفهمــا لنفــس املتهمــن ‪،‬حيــث أنــه مت القبــض علــى املدعــى‬\n‫عليهمــا بعــد توفــر معلومــات مفادهــا عــن وجــود شــخص (املدعــى عليــه‬\n‫الثانــي) لــه نشــاط يف ترويــج احلشــيش املخــدر ألحــد أعوانــه واســتعد‬\n‫املصــدر باالطاحــة بــه باجلــرم املشــهود فتــم مراقبــة املــروج و الوســيط ومت‬\n‫مشــاهدتهما يتقابلــون مــع أشــخاص مشــبوهني و قــام املصــدر باالتصــال‬\n‫علــى الوســيط املدعــى عليــه الثانــي وكانــت املكاملــة علــى مســمع مــن‬\n‫أفــراد الفرقــة القابضــة و طلــب منــه قطعــة حشــيش فدلــه علــى أحــد‬\n‫أعوانــه املتهــم املدعــى عليــه األول وقــام بإرســال رقــم هاتفــه للمصــدر‬\n‫فتــم االتصــال عليــه و أخبــره املصــدر بأنــه عــن طريــق املدعــى عليــه‬\n‫الثانــي فرحــب بــه و طلــب املصــدر منــه قطعــة حشــيش مببلــغ قــدره مائتــا‬\n‫ريــال فوافــق وحــدد مــكان االســتالم و التســليم ومت تفتيــش املصــدر‬\n‫تفتيشـ ًا دقيقـ ًا و مت ترقيــم املبلــغ احلكومــي وقــام أحــد األفــراد مبرافقــة‬\n\n                                                                                      ‫‪328‬‬\n\f      ‫املصــدر و مشــاهدة عمليــة الترويــج حيــث قــام بتســليم املصــدر قطعــة‬\n      ‫ســمراء اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر فتــم القبــض عليــه‬\n      ‫و بتفتيشــه عثــر معــه علــى اجلــوال الــذي مت التنســيق معــه و أقــر أمــام‬\n      ‫الفرقــة القابضــة بــأن لديــه باملنــزل حشــيش مخــدر وباالنتقــال للمنــزل‬\n      ‫عثــر باملجلــس علــى املبلــغ احلكومــي و علــى قطعــة ســمراء اللــون يشــتبه‬\n      ‫أن تكــون مــن احلشــيش املخــدر و كذلــك عثــر علــى ســيجارة ملفوفــه‬\n      ‫يشــتبه أن تكــون ممزوجــة باحلشــيش املخــدر كمــا مت القبــض علــى‬\n      ‫الوســيط املدعــى عليــه األول و بتفتيــش ســيارته عثــر علــى عــدد خمــس‬\n      ‫قطــع يشــتبه أن تكــون مــن احلشــيش املخــدر و علــى مســدس و اجلــوال‬\n      ‫املســتخدم يف اجلرميــة و قــد أثبــت التقريــر الكيميائــي إيجابيــة العينــات‬\n      ‫املرســلة ملــادة احلشــيش املخــدر ‪ ،‬كمــا أقــر املدعــى عليهمــا بالدعــوى‪،‬‬\n      ‫بنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامــة حــد املســكر عليهمــا‬\n      ‫وتعزيرهمــا بالســجن واجللــد واملنــع مــن الســفر ومصــادرة اجلــوالت‬\n      ‫والشــرائح املســتخدمة يف اجلرائــم وصــدق احلكــم مــن محكمــة‬\n                                                                        ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n      ‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 34883199‬وتاريــخ ‪1434/4/10‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 34165739‬وتاريــخ ‪1434/4/10‬ه ـ‬\n      ‫افتتحــت اجللســة يف يــوم الســبت ‪1434/4/20‬ه ـ الســاعة الثانيــة عشــرة‬\n\n‫‪329‬‬\n\f‫والنصــف وفيهــا قــدم املدعــي العــام ‪ .....‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي‬\n‫مدعي ًا عام ًا بدائرة اإلدعاء العام لفرع املنطقة الشــرقية أدعي على كل‬\n‫مــن‪ .... -1/‬اجلنســية مبوجــب الســجل املدنــي رقــم‪ ... -2/ .......‬ســعودي‬\n‫اجلنســية مبوجــب بطاقــة تنقــل وعمــل للنازحــن مــن الــدول العربيــة‬\n‫املجــاورة برقــم ‪ .....‬حيــث إنــه باالطــاع علــى محاضــر البــاغ واالتصــال‬\n‫والقبــض والتفتيــش تبــن أنــه يف يــوم االثنــن املوافــق ‪1434/2/ 25‬ه ـ‬\n‫توفــرت معلومــات ملكافحــة املخــدرات مــن أحــد مصادرهــم الســرية عــن‬\n‫وجــود شــخص يدعــى ‪ .....‬مــن ســكان حــي ‪ ............‬ويســتخدم اجلــوال‬\n‫رقــم (‪ )....‬لــه نشــاط بالتوســط يف ترويــج احلشــيش ألحــد أعوانــه ويدعــى‬\n‫‪ ....‬وأفــاد املصــدر بأنــه علــى اســتعداد باإلطاحــة بــه باجلــرم املشــهود‬\n‫فتــم مراقبــة املــروج والوســيط ومت مشــاهدتهم يتقابلــون مــع أشــخاص‬\n‫مشــبوهني وقــام املصــدر باالتصــال علــى الوســيط ‪ .......‬وكانــت‬\n‫املكاملــة علــى مســمع مــن أفــراد الفرقــة القابضــة وطلــب منــه قطعــة‬\n‫حشــيش فأخبــره الوســيط بأنــه يف شــاطئ ‪ ............‬ودلــه علــى أحــد‬\n‫أعوانــه املتهــم ‪ .....‬وقــام بإرســال رقــم هاتفــه للمصــدر فتــم االتصــال‬\n‫عليــه علــى اجلــوال رقــم (‪ )....‬وأخبــره املصــدر بأنــه عــن طريــق ‪ ....‬فرحــب‬\n‫بــه وطلــب املصــدر منــه قطعــة حشــيش مببلــغ مائتــن ريــال فوافــق‬\n‫وحــدد مــكان االســتالم والتســليم خلــف مجمــع كائــن بحــي ‪............‬‬\n‫بالدمــام ومت تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا إبــراء للذمــة ومت ترقيــم‬\n‫املبلــغ احلكومــي وقــام أحــد االفــراد مبرافقــة املصــدر ومشــاهدة عمليــة‬\n‫الترويــج فتحركــوا حتــت أنظــار الفرقــة القابضــة وتوقفــوا باملــكان‬\n‫احملــدد فحضــر املتهــم ‪ ....‬مترجــا علــى قدميــه ونــزل املصــدر وتقابــا‬\n‫حتــت أنظــار الفرقــة القابضــة ومتــت عمليــة الترويــج حيــث قــام بتســليم‬\n\n\n                                                                                      ‫‪330‬‬\n\f      ‫املصــدر قطعــة ســمراء اللــون يشــتبه بــأن تكــون مــن احلشــيش املخــدر‬\n      ‫بلــغ وزنهــا (‪)6.8‬ســتة جــرام وثمانيــة مــن العشــرة مــن اجلــرام فتــم القبــض‬\n      ‫عليــه وبتفتيشــه عثــر معــه علــى اجلــوال الــذي مت التنســيق معــه مــن نــوع‬\n      ‫‪ .....‬يحمــل الرقــم املصنعــي ‪ ............‬وأقــر أمــام الفرقــة القابضــة بأن لدية‬\n      ‫باملنــزل قطعــة حشــيش داخــل منزلــه وباالنتقــال للمنــزل عثــر باملجلــس‬\n      ‫علــى املبلــغ احلكومــي وعلــى قطعــة ســمراء اللــون يشــتبه بــأن تكــون‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )35.2‬خمســة وثالثــن جرام ـ ًا واثنــان‬\n      ‫مــن العشــرة مــن اجلــرام وعثــر كذلــك علــى ســيجارة ملفوفــة يشــتبة بــأن‬\n      ‫تكــون ممزوجــة باحلشــيش املخــدر بلــغ وزنهــا(‪ )1,2‬واحــد جــرام واثنــن‬\n      ‫مــن العشــرة مــن اجلــرام كمــا مت القبــض علــى الوســيط املتهــم ‪....‬‬\n      ‫وبتفتيــش ســيارته مــن نــوع ‪ ......‬حتمــل اللوحــة رقــم (‪( )......‬مت تســليمها‬\n      ‫لصاحبهــا) عثــر بداخلهــا علــى علبــة نظــارات وجــد بداخلهــا عــدد خمــس‬\n      ‫قطــع ســمراء اللــون يشــتبه بــأن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫جميع ـ ًا (‪ )28,6‬ثمانيــة وعشــرون جــرام وســته مــن العشــرة مــن اجلــرام‬\n      ‫وعثــر علــى مســدس ربــع أســباني مــع مخزنــن فارغــة (مت بعثــة جلهــة‬\n      ‫االختصــاص لفحصــه واعــداد تقريــر بذلــك) وعثــر معــه كذلــك علــى‬\n      ‫هاتفــه الــذي اســتخدمه يف عمليــة الترويــج مــن نــوع ‪ .......‬يحمــل الرقــم‬\n      ‫املصنعــي (‪ )............‬وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪1074‬‬\n      ‫ك ش) لعــام ‪1434‬ه ـ إيجابيــة العينــات املرســلة مــن الكميــة املروجــة‬\n      ‫والكميــة املضبوطــة مــع املتهمــن ملــادة احلشــيش املخــدر وباســتجواب‬\n      ‫املتهــم األول ‪ ....‬أقــر بقيامــه بعمليــة الترويــج كمــا أقــر بحيازتــه للكمية‬\n      ‫املضبوطــة داخــل منزلــه البالــغ وزنهــا(‪ )35.2‬خمســة وثالثــن جرام ـ ًا‬\n      ‫واثنــان مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر وســيجارة ملفوفــة‬\n\n\n‫‪331‬‬\n\f‫ممزوجــة باحلشــيش املخــدر بلــغ وزنهــا (‪ )1,2‬واحــد جــرام واثنــن مــن‬\n‫العشــرة مــن اجلــرام بقصــد التعاطــي وأقــر بأنــه يتعاطــى احلشــيش املخــدر‬\n‫باســتجواب املتهــم الثانــي ‪ ...‬أقــر بقيامــه بالتوســط يف عمليــة الترويــج‬\n‫كمــا أقــر بحيازتــه للكميــة املضبوطــة داخــل الســيارة البالــغ عددهــا‬\n‫(‪ )5‬قطــع حشــيش بلــغ وزنهــا جميع ـ ًا (‪ )28,6‬ثمانيــة وعشــرين جرام ـ ًا‬\n‫وســته مــن العشــرة مــن اجلــرام بقصــد التعاطــي‪ ،‬وأقــر بأنــه يتعاطــى‬\n‫احلشــيش املخــدر وأنــه يقــوم بإعطــاء املتهــم األول احلشــيش املخــدر بــدون‬\n‫مقابــل وقــد انتهــى التحقيــق إلــى اتهــام كل مــن ‪ .... ...‬باالتــي‪-1 :‬بيــع‬\n‫املتهــم األول ‪ ...‬لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)6,8‬ســتة جــرام‬\n‫وثمانيــة مــن العشــرة مــن اجلــرام بقصــد االجتــار ‪-2‬توســط املتهــم الثانــي‬\n‫‪...‬يف بيــع قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا بلــغ وزنهــا (‪)6,8‬ســتة‬\n‫جــرام وثمانيــة مــن العشــرة مــن اجلــرام بقصــد االجتــار ‪-3‬حيــازة املتهــم‬\n‫األول لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )35.2‬خمســة وثالثــن‬\n‫جرام ـ ًا واثنــان مــن العشــرة مــن اجلــرام وســيجارة ملفوفــة ممزوجــة‬\n‫باحلشــيش املخــدر بلــغ وزنهــا (‪ )1,2‬واحــد جــرام واثنــن مــن العشــرة‬\n‫مــن اجلــرام بقصــد التعاطــي والترويــج ‪-4‬حيــازة املتهــم الثانــي عــدد‬\n‫خمــس قطــع مــن احلشــيش املخــدر بلــغ وزنهــا جميع ـ ًا (‪ )28,6‬ثمانيــة‬\n‫وعشــرون جــرام وســته مــن العشــرة مــن اجلــرام بقصــد التعاطــي والترويــج‬\n‫‪-5‬قيــام املتهــم الثانــي يف الســابق بإهــداء احلشــيش املخــدر للمتهــم‬\n‫األول ‪-6‬تعاطيهمــا للحشــيش املخــدر وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬إقرارهمــا مبــا اســند إليهمــا واملرفــق بــاألوراق لفــه رقــم (‪-17-16‬‬\n‫‪ -2)20-19-18‬مــا ورد مبحضــر والقبــض املرفــق بــاألوراق لفــه رقــم‬\n‫(‪ -3 )1‬مــا ورد بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه‬\n\n\n                                                                                    ‫‪332‬‬\n\f      ‫(‪ -4)22‬وجــود خمــس قطــع مقســمة بســيارة املتهــم الثانــي دليــل علــى‬\n      ‫أنهــا معــدة للترويــج وبالبحــث عــن ســوابقهما لــم يعثــر لهمــا علــى ســوابق‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة‬\n      ‫شــرع ٌا فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا أطلــب اآلتــي‪ -1:‬إثبــات‬\n      ‫مــا أســند إليهمــا وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واحلكــم عليهمــا بالعقوبــة الــواردة بالفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار‬\n      ‫إليــه وتطبيــق العقوبــة األشــد وفقــا للفقــرة(‪ )1‬مــن املــادة (‪)62‬مــن نظــام‬\n      ‫مكافحــة املخــدرات ‪ -2‬احلكــم مبنعهمــا مــن الســفر وفق ـ ٌا للفقــرة‬\n      ‫رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات ‪ -3‬احلكــم‬\n      ‫مبصــادرة الهاتــف اجلــوال العائــد للمتهــم األول مــن نــوع (‪ )......‬يحمــل‬\n      ‫الرقــم املصنعــي (‪ )............‬ورقــم االتصــال(‪ )....‬والهاتــف اجلــوال العائــد‬\n      ‫للمتهــم الثانــي مــن نــوع (‪ ).......‬يحمــل الرقــم املصنعــي (‪ )............‬ورقــم‬\n      ‫االتصــال(‪ )....‬الســتخدامهما يف الترويــج وفق ـ ٌا للفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة (‪ )53‬مــن ذات النظــام مــع احلكــم بإســقاط شــريحة الهاتفــن‬\n      ‫اجلــوال وعــدم صرفهــا لنفــس املتهمــن وفقـ ًا لتعميــم ســمو وزيــر الداخليــة‬\n      ‫رقــم (‪)9798‬وتاريــخ ‪1428/10/23‬ه ـ هكــذا ادعــى وبعــرض الدعــوى‬\n      ‫علــى املدعــى عليــه ‪ ...‬قــال مــا ذكــره املدعــي العــام مــن قيامــي ببيــع‬\n      ‫احلشــيش املخــدر بقصــد االجتــار وكذلــك قيامــي بحيــازة للحشــيش‬\n      ‫للترويــج والتعاطــي وكذلــك قيامــي بتعاطــي احلشــيش املخــدر فذلــك‬\n      ‫صحيــح كلــه وقــد اســتخدمت اجلــوال يف التنســيق للبيــع وأنــا تائــب مــن‬\n      ‫هــذا العمــل وال توجــد علــي ســوابق هكــذا أجــاب كمــا أجــاب املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام مــن قيامــي بالتوســط‬     ‫عليــه الثانــي ‪ ....‬قائ ـ ً‬\n\n\n‫‪333‬‬\n\f‫يف بيــع احلشــيش وحيــازة احلشــيش بقصــد التعاطــي وقيامــي يف الســابق‬\n‫بإهــداء احلشــيش لــ‪ ............‬وكذلــك قيامــي بتعاطــي احلشــيش فذلــك‬\n‫صحيــح كلــه وقــد اســتخدمت اجلــوال يف التنســيق للبيــع وأنــا تائــب مــن‬\n‫هــذا العمــل وال توجــد علــي ســوابق هكــذا أجــاب ثــم جــرى الرجــوع‬\n‫إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬دفتــر التحقيــق ص (‪)12-11‬‬\n‫محضــر واقعــة القبــض والضبــط والتفتيــش وهــو طبــق مــا ذكــر املدعــي‬\n‫العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )22‬تقريــر كيمــاوي‬\n‫شــرعي رقــم (‪1074‬ك ش ) املتضمــن ايجابيــة العينــات املرســلة ملــادة‬\n‫احلشــيش املخــدر كمــا وجــدت علــى لفــة رقــم (‪ )27-25‬كــرت بصمات‬\n‫ـاء علــى مــا تقــدم‬\n                   ‫املدعــى عليهمــا املتضمــن عــدم وجــود ســوابق لهمــا فبنـ ً‬\n‫مــن دعــوى املدعــي العــام وإجابــة املدعــى عليهمــا وإقرارهمــا بالدعــوى‬\n‫ـاء علــى الفقــرة (‪ )2‬مــن املادة‬\n                                 ‫وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا وبنـ ً‬\n‫رقــم (‪ )3‬والفقــرة (‪ )1‬مــن املــادة رقــم (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪)53‬‬\n‫والفقــرة (‪ )1‬مــن املــادة رقــم (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )60‬والفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫ونظــر ًا لعــدم وجــود ســوابق علــى املدعــى عليهمــا وملــا ظهــر منهمــا مــن‬\n‫إبدائهمــا للنــدم علــى فعلهمــا ومبــا أن احلشــيش مســكر حيــث ذكــر‬\n‫شــيخ اإلســام ابــن تيميــة يف مجمــوع الفتــاوى مــا نصــه‪( :‬والصحيــح أن‬\n‫احلشيشــة مســكرة كالشــراب وأن آكلهــا يحــد منهــا فهــي خمــر )‬\n                                                                     ‫(ج‪/29‬ص‪)135‬‬\n‫كمــا قــال‪( :‬وفيهــا مــن املفاســد مــا ليــس يف اخلمــر وإن كان يف اخلمــر‬\n‫مفســدة ليســت فيهــا وهــي احلــدة فهــي بالتحــرمي أولــى مــن اخلمــر ألن‬\n‫ضــرر آكل احلشيشــة علــى نفســه أشــد مــن ضــرر اخلمــر وضــرر شــارب‬\n\n\n                                                                                        ‫‪334‬‬\n\f      ‫اخلمــر علــى النــاس أشــد إال أنــه يف هــذه األزمــان لكثــرة أكل احلشيشــة‬\n      ‫صــار الضــرر الــذي منهــا علــى النــاس أعظــم مــن اخلمــر) مجمــوع الفتاوى‬\n      ‫(ج‪/29‬ص‪ )142‬لــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليهمــا كل‬\n      ‫مــن‪ ... ..... /‬باآلتــي‪-1 :‬بيــع ‪ ............‬لقطعــة مــن احلشــيش املخــدر بلــغ‬\n      ‫وزنهــا (‪)6,8‬ســتة جرامــات وثمانيــة مــن العشــرة مــن اجلــرام بقصــد‬\n      ‫االجتــار ‪-2‬توســط ‪ ...‬يف بيــع قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫بلــغ وزنهــا (‪)6,8‬ســتة جــرام وثمانيــة مــن العشــرة مــن اجلــرام بقصــد‬\n      ‫االجتــار ‪-3‬حيــازة ‪ ....‬لقطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪)35.2‬‬\n      ‫خمســة وثالثــن جرامـ ًا واثنــان مــن العشــرة مــن اجلــرام وســيجارة ملفوفــة‬\n      ‫ممزوجــة باحلشــيش املخــدر بلــغ وزنهــا (‪ )1,2‬واحــد جــرام واثنــن مــن‬\n      ‫العشــرة مــن اجلــرام بقصــد التعاطــي والترويــج ‪-4‬حيــازة املتهــم ‪ ....‬لعــدد‬\n      ‫خمــس قطــع مــن احلشــيش املخــدر بلــغ وزنهــا جميع ـ ًا (‪ )28,6‬ثمانيــة‬\n      ‫وعشــرين جرامـ ًا وســتة مــن العشــرة مــن اجلــرام بقصــد التعاطــي ‪-5‬قيــام‬\n      ‫‪ ............‬يف الســابق بإهداء احلشــيش املخدر ل‪-6 ...‬تعاطيهما للحشــيش‬\n      ‫املخــدر وقــررت معاقبتهمــا علــى ذلــك مبــا يلــي‪ :‬أوالً‪ :‬ســجن كل واحــد‬\n      ‫ـداء مــن تاريــخ إيقــاف‬‫مــن املدعــى عليهمــا ملــدة ســنتني وســتة أشــهر ابتـ ً‬\n      ‫كل واحــد منهمــا وجلــد كل واحــد منهمــا مائتــن وخمســن جلــدة‬\n      ‫تعزيــر ًا مفرقــة علــى دفعــات متســاوية بــن كل دفعــة وأخــرى مــدة‬\n      ‫التقــل عــن أســبوعني وتغــرمي كل واحــد منهمــا ألــف ريــال تدفــع للجهــة‬\n      ‫املختصــة وذلــك لقــاء بيــع احلشــيش والتوســط يف بيعــه وحيازتــه‪ .‬ثاني ـاً‪:‬‬\n      ‫منــع كل واحــد مــن املدعــى عليهمــا مــن الســفر ملــدة ســنتني وســتة‬\n      ‫أشــهر بعــد انتهــاء محكوميتهمــا املقــررة يف البنــد أوالً‪ .‬ثالثـاً‪ :‬مصــادرة‬\n      ‫اجلــواالت املوصــوف يف الدعــوى وإيداعهــا أو ثمنهــا لــدى اجلهــة املختصــة‬\n\n\n‫‪335‬‬\n\f‫وعــدم صــرف شــريحة اجلــوال لــكل واحــد منهمــا مــرة أخــرى‪ .‬رابع ـاً‪:‬‬\n‫جلــد كل واحــد مــن املدعــى عليهمــا ثمانــن جلــدة دفعــة واحــدة حــد‬\n‫املســكر ويكــون يف مــكان عــام بــن جمــع مــن النــاس‪ .‬وبــكل مــا‬\n‫تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليهمــا‬\n‫القناعــة باحلكــم وأمــا املدعــي العــام فقــرر االعتــراض واالكتفــاء‬\n‫بالئحــة الدعــوى العامــة وأمــرت برفــع املعاملــة إلــى محكمــة االســتئناف‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                  ‫حــرر يف ‪1434/04/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت ‪1434/06/17‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة والنصــف وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n‫االستئناف باملنطقة الشرقية برقم ‪ 34/1173702‬يف ‪1434/06/07‬هـ‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة برقــم ‪34223687‬‬\n‫يف ‪1434/05/27‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                            ‫‪1434/06/17‬هـ‬\n\n\n\n\n                                                                                   ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":327,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c851ea68fa4e311aecbc5219dec0e0024a73ce362b863130fff3bd3249f754e3","normalized_text_hash":"0c51c03d7f131151c7de37659d421df265a0e413040d4d2f5d6354a7c2d9ad1a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p327-34196192"},{"id":"e86abe0f-feed-593c-82ca-1417bcceeb1e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -حيازة حبوب محظورة بقصد التعاطي -إقرار -إدانة -تعزير بالسجن واجللد والغرامة واإلبعاد","document_number":"34215354","case_number":"34169514","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/9","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -حيازة حبوب محظورة بقصد التعاطي -إقرار -إدانة -تعزير بالسجن واجللد والغرامة واإلبعاد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34215354 :‬تاريخه ‪1434/05/9 :‬هـ‬\n                          ‫رقم الدعوى ‪34169514 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34250136‬تاريخه‪1434/06/24:‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬حيــازة حبــوب محظــورة بقصــد‬\n       ‫التعاطــي ‪ -‬إقــرار ‪ -‬إدانــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واإلبعــاد‬\n                                                                          ‫عــن البــاد ‪.‬‬\n\n\n\n\n       ‫املــواد ( ‪ - 60‬الفقــرة الثانيــة مــن املــادة ‪ ) 56‬مــن نظام مكافحة املخدرات‬\n                                                              ‫واملؤثرات العقلية ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليــه ببيــع احلبــوب احملظــورة بقصــد‬\n       ‫االجتــار و الترويــج وحيــازة احلبــوب احملظــورة لقصــد الترويــج وتعاطيــه‬\n       ‫لهــا ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n       ‫الســجن واجللــد والغرامــة املاليــة وإبعــاده إلــى خــارج البــاد بعــد انتهــاء‬\n       ‫تنفيــذ العقوبــة وعــدم الســماح لــه بالعــودة مــرة أخــرى وعقوبتــه تعزيــر ًا‬\n       ‫لقــاء تســتره علــى مصــدر مــا باعــه ومــا ضبــط ‪ ،‬مت القبــض علــى املدعــى‬\n       ‫عليــه بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم بترويــج احلبــوب‬\n       ‫احملظــورة ومت التنســيق مــع أحــد املصــادر الســرية لإليقــاع بــه متلبس ـ ًا‬\n       ‫وتقابــل املصــدر مــع املدعــى عليــه يف املوقــع احملــدد ومت القبــض علــى‬\n       ‫املدعــى عليــه بعــد عمليــة االســتالم والتســليم إقــرار املدعــى عليــه‬\n\n‫‪337‬‬\n\f‫بالدعــوى وحكمــت احملكمــة بتعزيــره بالســجن واجللــد والغرامــة‬\n‫واإلبعــاد عــن البــاد ‪ ،‬قنــع املدعــى عليــه وقــرر املدعــي العــام االعتــراض‬\n            ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬       ‫بغيــر الئحــة ‪ُ -‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34169514‬وتاريــخ ‪ 1434/04/14‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34904477‬وتاريــخ ‪ 1434/04/14‬ه ـ ففــي يــوم‬\n‫الثالثــاء املوافــق‪ 1434/05/14‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n‫وفيهــا حضــر املدعــي العــام وقــدم الئحــه دعــوى عامــه نصهــا كالتالــي ‪:‬‬\n‫فبصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام مبدينــة الريــاض ادعــي‬\n‫علــى ‪ ....../‬البالــغ مــن العمــر (‪ )23‬عامـ ًا ‪ ،‬مينــي اجلنســية مبوجــب رخصة‬\n‫اإلقامــة رقــم (‪ ).....................‬أعــزب ‪ -‬متعلــم ‪ -‬يقيــم مبدينــة الريــاض ‪-‬‬\n‫أوقف بتاريخ ‪1434/2/24‬هـ وأحيل إلى شــعبه ســجن امللز مبوجب أمر‬\n‫اإلحالــة ومتديــد التوقيــف رقــم (ه ـ ر‪ )21766/5/1‬وتاريخ ‪1434/3/1‬هـ‬\n‫اســتناد ًا إلــى القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي‬\n                             ‫علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬‬\n‫حيــث إنــه بتاريــخ ‪1434/2/24‬ه ـ توفــرت معلومــات لــدى إحــدى فــرق‬\n‫إدارة العمليــات التابعــة ملكافحــة املخــدرات مبنطقــة الريــاض مــن أحــد‬\n‫املصــادر الســرية عــن قيــام املذكــور بترويــج احلبــوب احملظــورة عليــه‬\n‫جــرى االنتقــال إلــى املوقــع حيــث شــوهد املذكــور واقــف علــى قدميــه‬\n‫يف أحــد الشــوارع املنزويــة فتــم تفتيــش املصــدر تفتيش ـ ًا دقيق ـ ًا وتزويــده‬\n\n                                                                                         ‫‪338‬‬\n\f      ‫باملبلــغ احلكومــي املرقــم وقــدره (‪ )100‬مائــة ريــال ومت اإليعــاز للمصــدر‬\n      ‫بالترجــل مــن ســيارة الفرقــة وتوجــه للمذكــور واحتــك بــه علــى مــرأى‬\n      ‫مــن رقيــب الفرقــة وســلمه املصــدر املبلــغ احلكومــي املرقــم وســلم‬\n      ‫املذكــور للمصــدر (‪ )2‬حبتــن حتمــان عالمــة الكبتاجــون احملظــور‬\n      ‫عندهــا أعطيــت االشــارة الدالــة علــى إمتــام عمليــة الترويــج فتمــت‬\n      ‫مداهمــة املــروج والقبــض عليــه وبتفتيشــه شــخصي ًا عثــر بجيــب بنطالــه‬\n      ‫األيســر علــى كيــس نايلــون بداخلــه (‪ )78‬ثمــان وســبعون حبــة بنيــة‬\n      ‫اللــون حتمــل عالمــة الكبتاجــون احملظــور كمــا عثــر باجليــب نفســه‬\n      ‫علــى املبلــغ احلكومــي املرقــم (متــت مطابقتــه) ومبناقشــته عــن واقعــة‬\n      ‫الترويــج أقــر بكامــل تفاصيلهــا علــى مســمع مــن الفرقــة القابضــة‬\n      ‫(مت رد اجلــوال املضبــوط معــه مــن نــوع ‪ ......‬مبوجــب اخلطــاب رقــم (ه ـ‬\n      ‫ا للمصــادرة‬ ‫ر‪ )29749/5/1‬وتاريــخ ‪1434/2/22‬ه ـ لكونــه ليــس محـ ً‬\n      ‫اســتناد ًا للمــادة (‪ )86‬مــن نظــام اإلجــراءات اجلزائيــة) ‪.‬وقــد أثبــت التقرير‬\n      ‫الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة الســموم والكيميــاء‬\n      ‫الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪/2268‬س) لعــام ‪1434‬ه ـ‬\n      ‫احتــواء احلبتــن املبيعــة وعينــة احلبــوب املضبوطــة ملــادة اإلمفيتامــن وهــو‬\n      ‫مــن املــواد املنبهــه واملدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) امللحــق بنظــام‬\n                                       ‫مكافحــه املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫وبســماع أقوالــه األوليــة واســتجوابه أقــر ببيــع (‪ )2‬حبتــان مــن حبــوب‬\n      ‫اإلمفيتامــن املنبــه احملظــور وحيازتــه (‪ )78‬ثمــان وســبعون حبــه مــن‬\n      ‫حبــوب الكبتاجــون بقصــد االجتــار والترويــج وتعاطيــه إياهــا ودون لــه‬\n                                                                       ‫إقــرار بذلــك ‪.‬‬\n      ‫وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام لــ‪ /‬ببيــع (‪)2‬‬\n\n\n‫‪339‬‬\n\f‫حبتــان مــن حبــوب اإلمفيتامــن املنبــه احملظــور بقصــد االجتــار والترويــج‬\n‫وحيازتــه (‪ )78‬ثمــان وســبعون مــن حبــوب اإلمفيتامــن املنبــه احملظــور‬\n‫بقصــد الترويــج وتعاطيــه إياهــا املجــرم مبوجــب املــادة (الثالثــة) مــن نظام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬وتســتره علــى مصــدر مــا باعــه ومــا‬\n                                              ‫ضبــط املعاقــب علــى ذلــك شــرع ًا ‪.‬‬\n                                                   ‫وذلك لألدلة والقرائن التالية ‪-:‬‬\n‫‪ -1‬مــا تضمنــه اعترافــه حتقيقـ ًا املنــوه عنــه املــدون علــى الصفحتــن رقــم‬\n                           ‫(‪ )2-1‬مــن دفتــر التحقيــق املرفــق لفــه رقــم (‪. ) 13‬‬\n‫‪ -2‬مــا تضمنــه إقــرار املذكــور املنــوه عنــه املــدون علــى الصفحــة رقــم‬\n                             ‫(‪ )3‬مــن دفتــر التحقيــق املرفــق لفــه رقــم ( ‪. ) 13‬‬\n‫‪ -3‬مــا تضمنــه اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املرفق‬\n                                                          ‫علــى اللفتــن رقــم (‪. )4-3‬‬\n‫‪ -4‬مــا تضمنــه محضــر القبــض ومحضــر مطابقــة املبلــغ املرقــم املنــوه‬\n‫عنهمــا واملدونــان علــى الصفحتــن رقــم (‪ )2-1‬مــن ملــف إجــراءات‬\n                                              ‫االســتدالل املرفــق لفــه رقــم (‪. )1‬‬\n‫‪ -5‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق علــى‬\n                                                                ‫اللفــة رقــم ( ‪. ) 20‬‬\n‫وببحــث ســوابقه اتضــح عــدم وجــود ســوابق مســجلة عليــه حتــى تاريخــه‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظام ـ ًا ‪ ،‬لــذا اطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه‬\n                                                                            ‫باآلتــي‪-:‬‬\n‫‪ -1‬بعقوبــة الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة (األولــى)‬\n\n\n                                                                                         ‫‪340‬‬\n\f      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n      ‫إليــه وتشــديد العقوبــة عليــه وفق ـ ًا للفقــرة (ج) مــن بنــد (ثاني ـاً) مــن ذات‬\n      ‫املــادة املشــار إليهــا ‪ ،‬وإعمــال الفقــرة (األولــى) مــن املــادة (‪ )62‬مــن ذات‬\n                                                                           ‫النظــام بحقــه ‪.‬‬\n      ‫‪ -2‬إبعــاده إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتــه وعــدم الســماح‬\n                                                  ‫لــه بالعــودة إليهــا مــرة أخــرى وفقـ ًا‬\n                          ‫للفقرة (الثانية) من املادة (‪ )56‬من النظام املشار إليه ‪.‬‬\n      ‫‪ -3‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا باعــه ومــا ضبــط‬\n                                                                       ‫‪ .‬هــذه دعــواي ‪.‬‬\n      ‫وبســؤال املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام مــن‬\n      ‫اتهامــي ببيــع حبتــن محظــوره صحيــح ووجــد بحوزتــي ثمــان وســبعني‬\n      ‫حبــة مــن نفــس النــوع حتمــل عالمــه الكبتاجــون عائــدة لــي بقصــد‬\n      ‫الترويــج وقــد تعاطيــت هــذا النــوع مــن احلبــوب ونــادم علــى مــا حصــل‬\n      ‫منــي وتائــب وليــس علــي ســوابق واشــتريت هــذه احلبــوب مــن شــخص‬\n      ‫يف ‪ ............‬يقــول ان هكــذا اجــاب ‪ .‬وباالطــاع علــى املعاملــه وجــدت‬\n      ‫باللفــه (‪ )20‬تقريــر كيميائــي برقــم ‪/44/2/2268‬ك يف ‪1434/3/8‬هـ‬\n      ‫مضمونــه املرســل (أ) عبــاره عــن حبتــن حتمــل عالمــه الكبتاجــون ثبــت‬\n      ‫احتــواء كل حبــه منهــا ملــاده االمفيتامــن واملرســل (ب) عبــاره عــن ســت‬\n      ‫حبــات ثبــت احتــواء كل حبــه ملــاده االمفيتامــن ووجــدت باللفــه (‪)14‬‬\n      ‫بيــان مــن االدلــه اجلنائيــه تضمــن عــدم وجــود ســوابق بحقــه وباالطــاع‬\n      ‫علــى رخصــه اقامتــه وجــدت تاريــخ ميــاده ‪1411/4/7‬ه ـ ‪ .‬فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واالجابــه وحيــث صــادق املدعــى عليــه املدعــي‬\n      ‫العــام يف دعــواه ولعــدم وجــود ســوابق بحقــه ولصغــر ســنه حســب رخصــة‬\n\n\n‫‪341‬‬\n\f‫اقامتــه ولقلــه احلبــوب التــي قــام ببيعهــا وملــا قــرره مــن النــدم والتوبــه‬\n‫وبنــاء علــى املــاده (‪ )60‬مــن نظــام مكافحــه املخــدرات لــذا قــررت‬\n‫النــزول عــن احلــد االدنــى املنصــوص عليــه يف املــاده (‪)38‬واملــاده (‪ )62‬مــن‬\n‫ذات النظــام وحكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬ثبــت لــدي ادانتــه‬\n‫ببيــع حبتــن مــن حبــوب االمفيتامــن احملظــور بقصــد االجتــار والترويــج‬\n‫وحيازتــه ثمــان وســبعني حبــه مــن حبــوب االمفيتامــن احملظــور بقصــد‬\n‫الترويــج ويعــزر لذلــك بســجنه ســنه اعتبــارا مــن تاريــخ توقيفــه وجلــده‬\n‫مائــه وخمســن جلــده مفرقــه علــى ثــاث دفعــات مســتاويه وتغرميــه‬\n‫الــف ريــال تدفــع للخزينــه العامــه للدولــه وابعــاده الــى خــارج اململكــه‬\n‫بعــد انتهــاء تنفيــذ عقوبــه ســجنه وفقــا للفقــره الثانيــه مــن املــاده(‪)56‬‬\n‫مــن ذات النظــام وثبــت لــدي ادانتــه بتعاطــي احلبــوب احملظــوره مــن ذات‬\n‫النــوع ويعــزر لذلــك بجلــده ســبعني جلــده دفعــه واحــده تنفــذ اوال وبعــد‬\n‫عشــره ايــام ينفــذ بحقــه الدفعــه االولــى مــن جلــد التعزيــر اعــاه كمــا‬\n‫ثبــت لــدي ادانتــه بتســتره علــى مصــدر مــا باعــه ومــا ضبــط بحوزتــه‬\n‫وتعزيــره علــى ذلــك داخــل يف التعزيــر اعــاه وبتــاوة احلكــم قنــع بــه‬\n‫املدعــى عليــه وقــرر املدعــي العــام اعتراضــه بــدون الئحــه وعليــه حصــل‬\n‫التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                           ‫يف ‪ 1434/05/14‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ 34904477‬وتاريــخ ‪/29‬‬\n‫‪ 1434/5‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمة‬\n‫الشــيخ‪ ............/‬املســجل برقــم ‪ 34215354‬وتاريــخ ‪1434/5 /19‬ه ـ‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪ ( ............/‬مينــي اجلنســية ) يف قضيــة‬\n      ‫مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل بــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قــررت الدائــرة املصادقــة علــى احلكــم ‪ .‬و اهلل املوفــق وصلــى اهلل علــى‬\n                                                 ‫نبينــا محمــد وآلــه وصحبــه وســلم‪0‬‬\n\n\n\n\n‫‪343‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"396a5809-4e7b-56b3-9eb0-4f45acc6dbb7","source_page_start":337,"source_page_end":343,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c4592bf447188b46612a5e5233191f189fec013f7f14eb044ac4d8c1d3e8ed14","normalized_text_hash":"2dd3a102a9405affbb03c9b60bfbe8a94fcebc0d6076ac07283d9714057ab4e8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v18-p337-34215354"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
